-- Records of chat_session
-- ----------------------------
INSERT INTO `chat_session`
VALUES ('2054521018593239041:0ffd9595-6fdc-49e5-bbe8-e1d32f2ae92d', 2054521018593239041, 'travel_manus',
        '0ffd9595-6fdc-49e5-bbe8-e1d32f2ae92d', '帮我规划青岛 3 天 2 晚行程',
        '你好！我是专注国内旅游规划的AI助手，可以帮你定制青岛3天2晚的行程——包括怎么玩、住哪方便、吃什么地道、大概花多少，还有避坑提醒 😊 请问你计划几月出发？有特别想体验的（比如海边漫步、老城拍照、海鲜大餐、崂山徒步）或需要照顾的同行人（如老人、孩子）吗？我来为你量身优化～',
        '2026-06-08 20:10:27', '2026-06-08 20:10:27');
INSERT INTO `chat_session`
VALUES ('2054521018593239041:19bf1a1b-9d99-4c4f-a50d-653a22e60dcb', 2054521018593239041, 'travel_app',
        '19bf1a1b-9d99-4c4f-a50d-653a22e60dcb', '你好',
        '你好！我是行旅 AI —— 一位专注新中式国风旅行体验的旅游咨询助手，愿以专业、真实、有温度的方式，陪你读懂山河诗意，安顿身心行旅。 目前你尚未提出具体目的地或问题，如： 想去哪里（比如苏州平江路、敦煌莫高窟、徽州古村、西安城墙）？ 关心什么（比如节气出行建议、汉服穿搭指南、小众非遗体验、带老人/孩子出游避坑、当地时令美食地图）？ 我随时为你梳理实用信息——从交通接驳细节、住宿美学推荐，到礼仪分寸与应急锦囊，皆兼顾文化厚度与生活温度。🌿 请告诉我你的旅行心意吧～',
        '2026-06-11 15:44:32', '2026-06-11 15:44:32');
