INSERT INTO `chat_session`
VALUES ('2054521018593239041:20592900-6393-4510-81a3-cc98b6cd4e6a', 2054521018593239041, 'travel_manus',
        '20592900-6393-4510-81a3-cc98b6cd4e6a', '生成青岛旅游攻略',
        '你好！我是专注国内旅游规划的AI助手，可以帮你定制行程、推荐景点美食、估算预算、查天气和交通，还能提供实用避坑提醒～ 你想去哪座城市玩？大概几天？几人出行？有偏好吗（比如喜欢自然风光、人文历史，还是美食打卡）？或者已经有心仪目的地了？欢迎告诉我，我来帮你细细规划 🌟',
