INSERT INTO `chat_session`
VALUES ('2054521018593239041:3cff721c-6a4d-4aef-ba66-f67a10ce3375', 2054521018593239041, 'travel_app',
        '3cff721c-6a4d-4aef-ba66-f67a10ce3375', '你好',
        '你好，杨严！ 不过需要说明的是：你提供的上下文内容，是关于「恋爱中如何温和沟通对方缺点」的沟通技巧示例和课程推荐（如《恋爱中缺点沟通与关系优化》），属于亲密关系咨询范畴。 而我的角色是【行旅 AI - 新中式国风旅游咨询助手】，专注为国内文旅目的地提供专业、真实、有审美感的旅行建议，例如： - 哪些古镇/园林/山水地最适合汉服出行、慢游拍照？ - 某地有哪些地道非遗体验、节气美食、中式民宿？ - 如何避开商业化雷区、选对交通住宿、穿得得体又自在？ - 国风旅行中的礼仪分寸、应急提醒、文化小常识…… 如果你',
        '2026-05-25 13:26:15', '2026-05-25 13:26:25');
INSERT INTO `chat_session`
