INSERT INTO `chat_session`
VALUES ('2054521018593239041:6e047cb6-aa9f-4139-a412-878012ef5841', 2054521018593239041, 'travel_manus',
        '6e047cb6-aa9f-4139-a412-878012ef5841', '你好，我是杨严',
        '你好，杨严！很高兴认识你～ 我是你的国内旅游规划助手，可以帮你： ✅ 规划城市深度游/周边短途游行程（比如成都4天怎么玩、苏州3日怎么逛） ✅ 推荐地道美食、小众景点、舒适住宿和靠谱交通方式 ✅ 估算真实预算（含门票、吃住、市内交通等） ✅ 查询实时天气、景区开放时间、最新政策提醒 你最近有想去的地方吗？比如： 📍 目的地（如“大理”“西安”“厦门”） 📅 出行时间 & 天数（如“五一假期5天”“暑假带娃10天”） 👥 出行人数 & 偏好（如“2人情侣游”“一家四口亲子”“喜欢拍照/爱逛博物馆/专程',
        '2026-05-25 13:20:54', '2026-05-25 13:25:02');
INSERT INTO `chat_session`
VALUES ('2054521018593239041:7469fa95-1380-42e4-ac28-fada667c488c', 2054521018593239041, 'workflow',
        '7469fa95-1380-42e4-ac28-fada667c488c', '生成青岛旅游攻略',
        '（很抱歉，行程生成失败，请稍后重试。错误：I/O error on POST request for \"https://dashscope.aliyuncs.com/api/v1/services/aigc/text-generation/generation\": timeout）',
        '2026-06-06 15:36:25', '2026-06-06 15:37:54');
INSERT INTO `chat_session`
VALUES ('2054521018593239041:882cd10a-8bc7-4ab2-b288-21e8f4c9d71c', 2054521018593239041, 'workflow',
        '882cd10a-8bc7-4ab2-b288-21e8f4c9d71c', '帮我规划青岛 3 天 2 晚行程',
        '# 青岛 行程建议 ## 行程总览 当前大模型响应超时，先返回一个简版行程。已采用默认值：人数按 2 人、预算按人均 600 元/天估算。 ## 每日安排 - Day 1：上午安排核心景点，下午安排体验/休闲，晚上安排餐饮与返程节奏。 - Day 2：上午安排核心景点，下午安排体验/休闲，晚上安排餐饮与返程节奏。 - Day 3：上午安排核心景点，下午安排体验/休闲，晚上安排餐饮与返程节奏。 ## 预算建议 - 参考总预算：3600 元 - 建议优先把预算分配给交通、住宿和门票 ## 贴士 - 以舒适慢行',
        '2026-06-11 15:45:44', '2026-06-11 16:07:09');
INSERT INTO `chat_session`
VALUES ('2054521018593239041:8c60e95a-8cb6-4c80-976c-b709a4b6714e', 2054521018593239041, 'travel_app',
        '8c60e95a-8cb6-4c80-976c-b709a4b6714e', '我是谁',
        '青岛三日游攻略（新中式国风视角 · 实用避坑版） 结论先行： 青岛是一座山、海、城共生的东方滨海名城，既有德式老建筑的沉静气韵，又有崂山道风与胶东渔火的人文厚度。三日行程建议以「红瓦绿树为骨、碧海蓝天为韵、山海人文为魂」，避开网红打卡陷阱，聚焦真实在地体验。 以下为兼顾审美感、实用性与避坑提示的原创行程—— 第一日｜老城漫步 · 中西合璧的时光褶皱 - 上午：【信号山公园】登顶俯瞰“红瓦绿树、碧海青天”全景，推荐穿素色棉麻或宋锦纹样改良衬衫，轻便舒适；山顶无强制消费，免费开放（8:00–18:00）。 -',
        '2026-05-25 13:26:39', '2026-06-06 15:26:43');
INSERT INTO `chat_session`
VALUES ('2054521018593239041:8e9e59c4-c44c-49a5-bf5a-8f45e0d465c9', 2054521018593239041, 'travel_manus',
        '8e9e59c4-c44c-49a5-bf5a-8f45e0d465c9', '生成青岛旅游攻略',
        '用户已明确表达旅行意图：“生成青岛旅游攻略”，属于「完整行程规划」类需求，且目的地（青岛）已确定。当前缺少天数、人数、预算、偏好等关键参数，按规则优先补全默认值： - 天数：未说明 → 默认 3 天（常见短途游基准） - 人数：未说明 → 默认 2 人 - 预算：未说明 → 按国内中等舒适水平估算，人均约 600 元/天 - 偏好：未说明 → 默认“经典景点 + 本地美食 + 轻松节奏” - 出行时间：未说明 → 不设限，但需在方案中提示季节适配建议 下一步应调用 generateTravelPlan 工',
        '2026-06-06 15:36:03', '2026-06-06 15:36:03');
INSERT INTO `chat_session`
VALUES ('2054521018593239041:9d164254-4088-42dd-991d-f1a78e751134', 2054521018593239041, 'workflow',
        '9d164254-4088-42dd-991d-f1a78e751134', '帮我规划青岛 3 天 2 晚行程',
        '（很抱歉，行程生成失败，请稍后重试。错误：I/O error on POST request for \"https://dashscope.aliyuncs.com/api/v1/services/aigc/text-generation/generation\": timeout）',
        '2026-06-08 18:44:30', '2026-06-08 18:44:30');
INSERT INTO `chat_session`
VALUES ('2054521018593239041:acd938ef-a0c4-498e-8657-462cef978835', 2054521018593239041, 'travel_manus',
        'acd938ef-a0c4-498e-8657-462cef978835', '你好我是张三',
        '你好张三！很高兴认识你～我是行旅 AI，专门帮你规划国内旅行，比如定制行程、推荐小众玩法、查实时天气和交通、估算预算，或者帮你找地道美食和舒适住宿。 想问问你：最近有想去的地方吗？比如城市、景点，或者有没有大致的出行时间、天数、几个人一起，还有偏好的风格（比如轻松逛吃、亲子友好、爱拍照打卡，或者想深度体验本地生活）？告诉我这些，我马上为你量身安排 🌟',
        '2026-05-25 13:25:28', '2026-05-25 13:25:28');
INSERT INTO `chat_session`
