-- ----------------------------
-- Table structure for rag_knowledge_document
-- ----------------------------
DROP TABLE IF EXISTS `rag_knowledge_document`;
CREATE TABLE `rag_knowledge_document`
(
    `id`                   bigint                                                        NOT NULL AUTO_INCREMENT COMMENT '主键 id',
    `title`                varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文档标题',
    `source_file`          varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL     DEFAULT NULL COMMENT '来源文件名',
    `content`              longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci     NOT NULL COMMENT '文档正文',
    `tags`                 varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL     DEFAULT NULL COMMENT '标签，逗号分隔',
    `status`               varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci  NOT NULL DEFAULT 'published' COMMENT '状态：draft / published / archived',
    `chunk_size`           int                                                           NOT NULL DEFAULT 1200 COMMENT '切块大小',
    `chunk_overlap`        int                                                           NOT NULL DEFAULT 120 COMMENT '切块重叠',
    `top_k`                int                                                           NOT NULL DEFAULT 3 COMMENT '检索 topK',
    `similarity_threshold` decimal(6, 4)                                                 NOT NULL DEFAULT 0.5000 COMMENT '相似度阈值',
    `embedding_version`    int                                                           NOT NULL DEFAULT 1 COMMENT '向量版本',
    `vectorized`           tinyint                                                       NOT NULL DEFAULT 0 COMMENT '是否已向量化：0 否 1 是',
    `created_at`           datetime                                                      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `updated_at`           datetime                                                      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (`id`) USING BTREE,
    INDEX `idx_rag_doc_status` (`status` ASC) USING BTREE,
    INDEX `idx_rag_doc_title` (`title` ASC) USING BTREE,
    INDEX `idx_rag_doc_source_file` (`source_file` ASC) USING BTREE,
    INDEX `idx_rag_doc_updated_at` (`updated_at` ASC) USING BTREE
) ENGINE = InnoDB
  AUTO_INCREMENT = 306
  CHARACTER SET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RAG 知识库文档表'
  ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rag_knowledge_document
-- ----------------------------
INSERT INTO `rag_knowledge_document`
VALUES (295, '交通与住宿攻略篇', '',
        '# 交通与住宿攻略篇\n\n## 第一部分：交通攻略\n\n### 1.1 交通选择通用原则\n\n#### 1.1.1 距离 - 时间 - 成本三维决策模型\n\n|行程距离|首选交通方式|备选方式|优势说明|\n|---|---|---|---|\n|**≤4 小时**|高铁 / 动车|自驾|准点率高 (>95%)、无需提前安检、可随时活动|\n|**4-8 小时**|高铁 / 夕发朝至火车|特价飞机|节省一晚住宿费，时间利用效率高|\n|**>8 小时**|飞机|高铁卧铺|长途耗时最短，舒适度更高|\n|**≤200 公里**|自驾 / 网约车|长途大巴|灵活性最强，适合携带大件行李|\n\n#### 1.1.2 不同人群交通偏好\n\n- **独行旅行者**：优先公共交通 + 网约车，成本低且安全\n\n- **家庭亲子游**：优先自驾 / 包车，便于照顾老人孩子\n\n- **老年游客**：优先高铁 / 飞机商务舱，避免长时间颠簸\n\n- **商务出行**：优先直达航班 / 高铁，确保准时到达\n\n### 1.2 城际交通攻略\n\n#### 1.2.1 航空出行\n\n**预订技巧（2026 最新）**：\n\n- **最佳预订时间**：国内提前 3-6 周，国际提前 2-4 个月\n\n- **低价搜索日**：周二晚上 20:00-22:00，周三上午 9:00-11:00\n\n- **价格波动规律**：上午价格偏高，下午 15:00 后逐渐下降\n\n- **避坑提示**：同一航线往返票不一定比两张单程便宜，务必分别比价\n\n**行李政策（2026 统一标准）**：\n\n- 随身携带：7kg 以内，尺寸≤20×40×55cm\n\n- 充电宝：≤100Wh 可随身携带，禁止托运\n\n- 液体：单瓶≤100ml，总量≤1L，透明密封袋包装\n\n**机场往返市区**：\n\n- 优先选择机场快线 / 地铁，比出租车便宜 50%-70%\n\n- 多人同行可预约接送机服务，人均成本更低\n\n- 避免乘坐机场门口主动拉客的 \"黑车\"\n\n#### 1.2.2 铁路出行\n\n**预订技巧**：\n\n- 提前 15 天放票，整点和半点会有退票回流\n\n- 热门线路可尝试 \"买长乘短\" 或 \"买短补长\"\n\n- 12306 候补功能成功率 > 80%，可同时候补多个车次\n\n**高铁选座指南**：\n\n- **A/F 座**：靠窗，适合观景和休息\n\n- **C/D 座**：靠过道，进出方便，适合长途\n\n- **B 座**：中间位置，最不推荐\n\n- **避开**：第 1 排和最后一排（空间小）、靠近卫生间和餐车的座位\n\n#### 1.2.3 自驾出行\n\n**出发前准备**：\n\n- 全面检查车况：轮胎、刹车、机油、冷却液\n\n- 下载离线地图，避免偏远地区信号不佳\n\n- 准备应急包：备胎、千斤顶、拖车绳、急救包\n\n**2026 自驾新趋势**：\n\n- 新能源汽车租车比例已超过 60%，成本比燃油车低 30%\n\n- 全国高速服务区充电桩覆盖率达 98%，充电无需长时间等待\n\n- 异地还车服务普及，单程自驾更便捷\n\n**停车攻略**：\n\n- 城市中心优先选择地下停车场，避免路边违章停车\n\n- 景区停车场通常早 8:00 前到达有车位\n\n- 可使用 \"捷停车\"、\"ETCP\" 等 APP 提前查询空位和缴费\n\n### 1.3 市内交通攻略\n\n#### 1.3.1 按目的地类型选择\n\n**都市目的地（北京、上海、广州等）**：\n\n- 首选：地铁 + 公交（成本最低、最便捷）\n\n- 短途：共享单车 / 电动车（3 公里内最佳）\n\n- 高峰时段：避免打车，拥堵严重\n\n**古城古镇目的地（丽江、平遥、凤凰等）**：\n\n- 内部：步行 + 观光车（多数古城禁止机动车）\n\n- 周边：共享电动车 + 网约车\n\n- 注意：不要相信 \"三轮车带你逛遍古城\" 的骗局\n\n**自然景区目的地（黄山、张家界、九寨沟等）**：\n\n- 景区内：观光车 + 索道（必须购买，节省大量体力）\n\n- 景区间：旅游专线大巴 + 包车\n\n- 偏远景区：提前预约返程车辆，避免无车可坐\n\n**海滨度假目的地（三亚、青岛、厦门等）**：\n\n- 沿海路线：租电动车骑行（体验最佳）\n\n- 跨区域：网约车 + 公交\n\n- 注意：海边停车费用较高，尽量选择住宿含停车位的\n\n#### 1.3.2 公共交通通用技巧\n\n- 下载当地官方交通 APP，支持实时查询和扫码乘车\n\n- 支付宝 / 微信 \"出行\" 功能已覆盖全国 95% 以上城市\n\n- 购买旅游一日票 / 三日票，比单次购票更划算\n\n- 早晚高峰（7:30-9:00，17:30-19:00）尽量避开公共交通\n\n### 1.4 交通避坑与安全指南\n\n#### 1.4.1 常见交通骗局\n\n- **机场 / 火车站拉客**：声称 \"酒店免费接送\"、\"低价包车\"，实际高价宰客\n\n- **出租车绕路**：要求打表，或使用导航软件监督路线\n\n- **景区直通车骗局**：非官方 \"直通车\" 会强制购物或加收费用\n\n- **假票诈骗**：务必通过官方渠道购买车票门票\n\n#### 1.4.2 交通安全提示\n\n- 不乘坐无牌无证、超载的交通工具\n\n- 乘坐网约车时，分享行程给亲友，核对车辆信息\n\n- 自驾时严禁疲劳驾驶，连续驾驶不超过 4 小时\n\n- 乘船时务必穿戴救生衣，遵守安全规定\n\n---\n\n## 第二部分：住宿攻略\n\n### 2.1 住宿类型与适用场景\n\n|住宿类型|价格区间 (国内)|适用人群|核心优势|注意事项|\n|---|---|---|---|---|\n|**经济型连锁酒店**|100-300 元 / 晚|学生、穷游者|标准化服务、安全可靠、分布广|设施简单，部分房间较小|\n|**中端商务酒店**|300-600 元 / 晚|商务人士、家庭|设施完善、含早餐、服务好|旺季价格波动大|\n|**高端星级酒店**|600 元以上 / 晚|高端游客、度蜜月|体验极佳、配套齐全、服务周到|价格昂贵，性价比低|\n|**特色民宿**|200-800 元 / 晚|情侣、文艺青年|设计独特、体验当地文化|服务参差不齐，卫生无保障|\n|**青年旅舍**|50-150 元 / 床位|独行旅行者、背包客|价格便宜、社交属性强|隐私性差，需要共用卫生间|\n|**短租公寓**|200-500 元 / 晚|长住游客、家庭|有厨房可做饭，空间大|入住退房流程较复杂|\n\n### 2.2 住宿位置选择黄金法则\n\n#### 2.2.1 通用选址原则\n\n- **交通优先**：距离地铁站 / 公交站步行≤10 分钟\n\n- **安全第一**：选择主干道旁、人流量大的区域\n\n- **成本平衡**：将房价与每日交通费用相加，选择总成本最低的\n\n- **行程匹配**：靠近主要景点或行程集中的区域\n\n#### 2.2.2 不同目的地选址建议\n\n**都市旅游**：\n\n- 首选：市中心地铁站附近\n\n- 次选：城市环线地铁站周边（价格低 30% 左右）\n\n- 避免：机场附近、工业区周边\n\n**古城古镇旅游**：\n\n- 首选：古城内或古城墙周边（步行可达景点）\n\n- 次选：古城外 1 公里范围内（价格低很多）\n\n- 避免：远离古城的新区（每天往返耗时太长）\n\n**海滨度假**：\n\n- 首选：海景房（步行≤5 分钟到海边）\n\n- 次选：离海边 1-2 公里的区域（性价比高）\n\n- 注意：一楼海景房潮湿且蚊虫多，高楼层视野更好\n\n**山区自然景区**：\n\n- 首选：景区门口或景区内的酒店（节省入园时间）\n\n- 次选：山下县城（价格低，选择多）\n\n- 避免：偏远的农家乐（交通不便，安全无保障）\n\n### 2.3 2026 年最新预订技巧\n\n#### 2.3.1 最佳预订时机\n\n|住宿类型|最佳预订窗口|价格波动幅度|\n|---|---|---|\n|城市商务酒店|提前 1-2 周|±20%|\n|度假型酒店|提前 2-4 个月|±50%|\n|热门景区民宿|提前 1-3 个月|±100%|\n|经济型连锁|提前 3-7 天|±15%|\n\n**特殊时段技巧**：\n\n- 工作日入住比周末便宜 20%-50%\n\n- 旺季前后 1-2 天入住，价格低且人少\n\n- 当天 18:00 后预订，部分酒店会放出特价房\n\n- 连住 3 晚以上通常有额外折扣\n\n#### 2.3.2 平台比价与优惠券\n\n**主流平台对比（2026）**：\n\n- **同程旅行**：优惠券最多，价格最低，覆盖广\n\n- **携程旅行**：酒店数量最多，服务有保障\n\n- **美团**：本地住宿优势明显，连住优惠大\n\n- **飞猪**：国际酒店和民宿资源丰富\n\n- **Booking**：境外预订首选，取消政策灵活\n\n**优惠券领取方法**：\n\n- 同程小程序搜索 \"惊喜 100\" 领取通用大额券\n\n- 各大平台会员日（每月 18 日左右）有专属优惠\n\n- 银行信用卡合作活动常有满减优惠\n\n- 关注酒店官方公众号，会员专享价更低\n\n#### 2.3.3 隐藏省钱技巧\n\n- **比价插件**：使用 \"慢慢买\"、\"什么值得买\" 等插件自动比价\n\n- **会员体系**：注册酒店集团会员，积分可兑换免费房晚\n\n- **套餐预订**：机票 + 酒店套餐比单独预订便宜 10%-30%\n\n- **尾单捡漏**：关注各大平台的 \"特价尾单\" 频道\n\n- **反向预订**：先预订可免费取消的房间，临近日期再看是否降价\n\n### 2.4 住宿避坑与维权指南\n\n#### 2.4.1 预订避坑\n\n- **仔细阅读取消政策**：部分特价房不可取消或收取高额手续费\n\n- **确认房型信息**：注意 \"无窗房\"、\"暗房\" 等特殊房型标注\n\n- **核实附加费用**：询问是否收取服务费、清洁费、停车费\n\n- **查看真实评价**：重点看近 1 个月的差评，关注卫生和服务问题\n\n#### 2.4.2 入住避坑\n\n- **入住检查**：检查房间卫生、设施是否完好，发现问题立即要求更换\n\n- **物品保管**：贵重物品随身携带或存入酒店保险箱\n\n- **隐私保护**：检查房间是否有针孔摄像头\n\n- **消费确认**：酒店内消费前务必确认价格，避免 \"天价消费\"\n\n#### 2.4.3 维权途径\n\n- 首先与酒店前台沟通解决\n\n- 沟通无果可联系预订平台客服介入\n\n- 仍无法解决可拨打 12315 消费者投诉热线\n\n- 保留好所有证据：订单截图、聊天记录、照片视频\n\n### 2.5 2026 年住宿新趋势\n\n#### 2.5.1 可持续住宿\n\n- 再生能源酒店：太阳能供电、雨水回收系统\n\n- 零废弃酒店：不提供一次性用品，使用可降解材料\n\n- 社区共生酒店：雇佣当地员工，采购当地食材\n\n#### 2.5.2 多功能住宿\n\n- 工作度假酒店：配备高速 WiFi、会议室、共享办公空间\n\n- 康养主题酒店：提供 SPA、瑜伽、冥想等健康服务\n\n- 亲子主题酒店：儿童乐园、亲子活动、儿童餐食\n\n#### 2.5.3 多站式住宿\n\n- \"酒店跳\"：在同一目的地选择 2-3 家不同风格的酒店\n\n- 长短结合：市区住酒店，郊区住民宿\n\n- 灵活入住：按小时计费的钟点房越来越普及\n\n---\n\n## 第三部分：交通与住宿预算控制\n\n### 3.1 预算分配比例参考\n\n- **交通费用**：占总预算的 30%-40%\n\n- **住宿费用**：占总预算的 30%-40%\n\n- **餐饮费用**：占总预算的 15%-25%\n\n- **门票费用**：占总预算的 10%-15%\n\n- **其他费用**：预留 10% 作为应急资金\n\n### 3.2 交通省钱技巧\n\n- 提前预订机票火车票，享受早鸟价\n\n- 选择红眼航班或凌晨车次，价格低很多\n\n- 多人出行选择包车，人均成本更低\n\n- 使用交通联合卡，享受全国公交地铁优惠\n\n- 避开节假日和旅游旺季出行\n\n### 3.3 住宿省钱技巧\n\n- 选择非核心区域的住宿，价格低 30%-50%\n\n- 结伴出行拼房，人均费用减半\n\n- 长住选择短租公寓，有厨房可自己做饭\n\n- 关注酒店尾单和限时秒杀活动\n\n- 使用会员积分兑换免费房晚\n\n---\n\n## 第四部分：应急处理\n\n### 4.1 交通延误处理\n\n- 航班延误：联系航空公司改签或退票，购买延误险可获赔偿\n\n- 火车晚点：可免费改签或退票，车站提供餐饮和住宿服务\n\n- 自驾故障：拨打保险公司救援电话，或联系租车公司处理\n\n### 4.2 住宿变更处理\n\n- 行程变更：提前联系酒店或平台取消预订，尽量避免损失\n\n- 酒店超售：要求酒店升级房型或安排附近同等级酒店\n\n- 房间不满意：立即要求更换，酒店有义务提供合格房间\n\n### 4.3 紧急联系方式\n\n- 全国统一报警电话：110\n\n- 医疗急救电话：120\n\n- 交通事故报警：122\n\n- 旅游投诉热线：12301\n\n- 外交部全球领事保护与服务应急热线：+86-10-12308',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:46:38', '2026-06-15 14:46:38');
INSERT INTO `rag_knowledge_document`
VALUES (296, '各地国风人文底蕴篇', '',
        '# 各地国风人文底蕴篇\n\n## 第一部分：国风人文目的地分类与核心代表\n\n### 1.1 古都名城类（华夏文明核心）\n\n|代表城市|核心人文亮点|必体验项目|最佳游览时间|\n|---|---|---|---|\n|**西安**|十三朝古都、盛唐文化、秦汉文明|大唐不夜城夜游、兵马俑考古体验、城墙骑行、碑林书法鉴赏|3-5 月、9-11 月|\n|**北京**|明清帝都、皇家建筑、胡同文化|故宫深度游、颐和园赏景、南锣鼓巷胡同漫步、国家博物馆|4-5 月、9-10 月|\n|**南京**|六朝古都、民国风情、江南文脉|明孝陵、夫子庙秦淮风光、总统府、老门东|3-5 月、9-11 月|\n|**洛阳**|十三朝古都、牡丹文化、佛教圣地|龙门石窟、白马寺、应天门灯光秀、牡丹节|4 月（牡丹节）、9-10 月|\n|**开封**|北宋都城、宋文化发源地|清明上河园实景演出、开封府、大相国寺|3-5 月、9-11 月|\n\n### 1.2 古镇水乡类（江南诗意生活）\n\n|代表古镇|核心人文亮点|必体验项目|最佳游览时间|\n|---|---|---|---|\n|**乌镇**|江南水乡典范、茅盾故里、互联网大会永久会址|摇橹船夜游、木心美术馆、西栅灯会、染坊体验|3-5 月、9-11 月|\n|**周庄**|中国第一水乡、明清建筑、沈万三文化|双桥观景、沈厅、南湖秋月园、万三蹄制作体验|3-5 月、9-11 月|\n|**宏村**|徽派建筑代表、世界文化遗产、中国画里乡村|月沼晨雾、南湖画桥、承志堂木雕、塔川秋色|3-4 月（油菜花）、10-11 月（秋色）|\n|**平遥**|保存最完整的明清古城、晋商文化发源地|古城墙漫步、日昇昌票号、县衙升堂表演、平遥牛肉制作|1-2 月（春节社火）、9-11 月|\n|**凤凰**|湘西苗族文化、沈从文故里、吊脚楼建筑|沱江泛舟、虹桥夜景、苗族银饰制作、边城实景演出|3-5 月、9-11 月|\n\n### 1.3 山水人文类（自然与文化交融）\n\n|代表景区|核心人文亮点|必体验项目|最佳游览时间|\n|---|---|---|---|\n|**黄山**|天下第一奇山、徽文化载体、徐霞客游记发源地|迎客松、西海大峡谷、宏村徽派建筑、黄山毛峰采摘|4-5 月（杜鹃花开）、9-11 月（秋色）|\n|**泰山**|五岳之首、帝王封禅圣地、书法石刻宝库|岱庙、十八盘、玉皇顶、封禅大典实景演出|4-5 月、9-11 月|\n|**武夷山**|世界双遗产、茶文化发源地、朱子理学圣地|九曲溪竹筏漂流、大红袍母树、武夷岩茶制作、朱熹故里|3-5 月、9-11 月|\n|**三峡**|长江文明、大国工程、巴楚文化|三峡大坝、白帝城、神农溪、屈原故里|4-5 月、9-11 月|\n|**桂林**|山水甲天下、壮族文化、喀斯特地貌|漓江游船、阳朔西街、龙脊梯田、壮族竹竿舞|4-5 月、9-11 月|\n\n### 1.4 宗教圣地类（千年信仰传承）\n\n|代表圣地|核心人文亮点|必体验项目|最佳游览时间|\n|---|---|---|---|\n|**五台山**|中国四大佛教名山之首、文殊菩萨道场|五爷庙祈福、显通寺、黛螺顶、素斋体验|6-8 月、9-10 月|\n|**普陀山**|观音菩萨道场、海天佛国|南海观音像、普济寺、法雨寺、慧济寺|3-5 月、9-11 月|\n|**峨眉山**|普贤菩萨道场、世界文化与自然双遗产|金顶日出、万年寺、清音阁、猴区|4-5 月、9-11 月|\n|**九华山**|地藏菩萨道场、莲花佛国|化城寺、肉身宝殿、百岁宫、天台峰|3-5 月、9-11 月|\n|**武当山**|道教圣地、太极拳发源地、皇家道场|金顶、紫霄宫、南岩宫、太极拳体验|3-5 月、9-11 月|\n\n### 1.5 民俗文化类（多彩民族风情）\n\n|代表地区|核心人文亮点|必体验项目|最佳游览时间|\n|---|---|---|---|\n|**贵州黔东南**|苗族侗族文化、千户苗寨、侗族大歌|西江千户苗寨、肇兴侗寨、苗族银饰制作、侗族大歌表演|4-5 月、9-11 月、4 月 30 日 - 5 月 10 日（苗族姊妹节）|\n|**云南大理**|白族文化、风花雪月、南诏古国|洱海骑行、大理古城、崇圣寺三塔、白族三道茶|3-5 月、9-11 月|\n|**福建泉州**|海上丝绸之路起点、闽南文化、世界宗教博物馆|开元寺、西街、蟳埔村簪花围、木偶戏|3-5 月、9-11 月|\n|**广东潮汕**|潮汕文化、工夫茶、英歌舞|潮州古城、广济桥、汕头小公园、英歌舞表演|1-2 月（春节）、3-5 月|\n|**山西晋中**|晋商文化、大院文化、传统年俗|乔家大院、王家大院、平遥古城、春节社火|1-2 月（春节）、9-11 月|\n\n### 1.6 红色文化类（革命历史记忆）\n\n|代表地区|核心人文亮点|必体验项目|最佳游览时间|\n|---|---|---|---|\n|**延安**|革命圣地、红色摇篮、黄土文化|宝塔山、杨家岭、枣园、延安革命纪念馆|4-5 月、9-11 月|\n|**井冈山**|中国革命的摇篮、井冈山精神发源地|茨坪、黄洋界、井冈山革命博物馆、红军小道|4-5 月、9-11 月|\n|**韶山**|毛泽东故里、红色文化教育基地|毛泽东故居、毛泽东纪念馆、滴水洞|3-5 月、9-11 月|\n|**遵义**|遵义会议会址、红军长征转折点|遵义会议会址、红军山、娄山关|3-5 月、9-11 月|\n|**西柏坡**|新中国从这里走来、最后一个农村指挥所|西柏坡纪念馆、中共中央旧址、五大书记故居|4-5 月、9-11 月|\n\n### 1.7 边境异域类（多元文化交融）\n\n|代表地区|核心人文亮点|必体验项目|最佳游览时间|\n|---|---|---|---|\n|**云南瑞丽**|中缅边境文化、一寨两国、傣族风情|一寨两国、姐告国门、莫里热带雨林、傣族泼水节|10 月 - 次年 4 月、4 月中旬（泼水节）|\n|**新疆喀什**|西域文化、维吾尔族风情、古丝绸之路重镇|喀什古城、艾提尕尔清真寺、香妃园、大巴扎|9-11 月|\n|**内蒙古呼伦贝尔**|蒙古族文化、草原风情、中俄边境|呼伦贝尔大草原、满洲里国门、套娃广场、那达慕大会|6-8 月（草原最美）、7-8 月（那达慕）|\n|**西藏拉萨**|藏传佛教文化、雪域高原风情、布达拉宫|布达拉宫、大昭寺、八廓街、纳木错|6-9 月|\n|**广西崇左**|中越边境文化、壮族风情、喀斯特地貌|德天瀑布、明仕田园、友谊关、壮族歌圩|4-5 月、9-11 月|\n\n---\n\n## 第二部分：国风人文深度体验指南\n\n### 2.1 古建筑观赏技巧\n\n**不同类型古建筑观赏重点**：\n\n- **宫殿建筑**：关注中轴线布局、屋顶形制（重檐庑殿顶等级最高）、斗拱结构、彩绘艺术、匾额楹联\n\n- **园林建筑**：欣赏借景、框景、对景等造园手法，关注假山、池水、花木、建筑的和谐搭配\n\n- **民居建筑**：了解当地地理气候对建筑的影响，观察建筑布局、装饰细节、生活设施\n\n- **宗教建筑**：注意建筑朝向、佛像布局、壁画雕塑、宗教仪式\n\n**最佳观赏时间**：\n\n- 清晨：光线柔和，游客稀少，适合拍摄和静心观赏\n\n- 傍晚：夕阳西下，古建筑被镀上金色，氛围感拉满\n\n- 雨天：烟雨朦胧，江南水乡和徽派建筑更显诗意\n\n- 夜晚：灯光映衬下，古建筑呈现出与白天不同的魅力\n\n### 2.2 非遗沉浸式体验（2026 最新热门）\n\n**传统手工艺类**：\n\n- **陶瓷制作**：景德镇拉坯、宜兴紫砂壶、德化白瓷\n\n- **纺织刺绣**：苏绣、湘绣、蜀绣、粤绣、苗族银饰、蜡染\n\n- **木作雕刻**：东阳木雕、黄杨木雕、核雕、竹编\n\n- **文房四宝**：宣纸制作、徽墨制作、湖笔制作、端砚雕刻\n\n**表演艺术类**：\n\n- **戏曲**：京剧、昆曲、越剧、黄梅戏、豫剧、秦腔\n\n- **曲艺**：相声、评书、大鼓、评弹\n\n- **舞蹈**：傣族孔雀舞、藏族锅庄舞、蒙古族安代舞、苗族芦笙舞\n\n- **杂技**：吴桥杂技、变脸、喷火\n\n**传统美食类**：\n\n- **面食制作**：山西刀削面、陕西 biangbiang 面、兰州拉面\n\n- **糕点制作**：北京烤鸭、天津麻花、苏州糕点、广式点心\n\n- **茶饮制作**：武夷岩茶、西湖龙井、普洱茶、福建工夫茶\n\n**2026 年非遗体验新趋势**：\n\n- 数字非遗：通过 VR/AR 技术沉浸式体验非遗制作过程\n\n- 非遗 + 民宿：在特色民宿中体验非遗项目，住非遗主题房间\n\n- 非遗 + 研学：针对青少年开发的非遗研学课程，边学边做\n\n- 非遗 + 文创：将非遗元素融入现代设计，购买非遗文创产品\n\n### 2.3 传统文化活动参与\n\n**2026 年主要传统节日活动时间表**：\n\n|节日|日期（公历）|主要活动|最佳体验地|\n|---|---|---|---|\n|春节|2026 年 2 月 17 日|贴春联、放鞭炮、吃年夜饭、逛庙会、看社火|平遥古城、西安、北京、山西晋中|\n|元宵节|2026 年 3 月 3 日|赏花灯、猜灯谜、吃元宵、舞龙舞狮|南京夫子庙、西安城墙、泉州、广州|\n|清明节|2026 年 4 月 5 日|扫墓祭祖、踏青、放风筝、吃青团|杭州、苏州、黄山、西安|\n|端午节|2026 年 6 月 19 日|赛龙舟、吃粽子、挂艾草、佩香囊|湖北秭归、湖南汨罗、浙江嘉兴、长沙|\n|七夕节|2026 年 8 月 19 日|穿针乞巧、拜织女、吃巧果、放河灯|杭州西湖、南京秦淮河、西安大唐不夜城|\n|中秋节|2026 年 9 月 25 日|赏月、吃月饼、赏桂花、猜灯谜|杭州西湖、苏州、扬州、厦门|\n|重阳节|2026 年 10 月 25 日|登高、赏菊、插茱萸、喝菊花酒|泰山、黄山、华山、北京香山|\n\n**其他特色文化活动**：\n\n- 洛阳牡丹文化节：4 月 1 日 - 5 月 10 日\n\n- 大理三月街：农历三月十五至二十一日\n\n- 傣族泼水节：4 月 13 日 - 15 日\n\n- 蒙古族那达慕大会：7 月 - 8 月\n\n- 彝族火把节：农历六月二十四日至二十六日\n\n### 2.4 美食文化溯源\n\n**中国八大菜系特色与代表菜**：\n\n- **鲁菜**：咸鲜为主，讲究火候，代表菜：糖醋鲤鱼、九转大肠、葱烧海参\n\n- **川菜**：麻辣鲜香，口味多变，代表菜：麻婆豆腐、水煮鱼、回锅肉\n\n- **粤菜**：清鲜爽嫩，注重原汁原味，代表菜：白切鸡、烧鹅、清蒸鱼\n\n- **苏菜**：清淡适口，刀工精细，代表菜：松鼠桂鱼、清炖狮子头、盐水鸭\n\n- **浙菜**：清鲜脆嫩，讲究造型，代表菜：东坡肉、西湖醋鱼、龙井虾仁\n\n- **闽菜**：酸甜清淡，擅长山珍海味，代表菜：佛跳墙、荔枝肉、醉排骨\n\n- **湘菜**：香辣浓郁，注重入味，代表菜：剁椒鱼头、辣椒炒肉、毛氏红烧肉\n\n- **徽菜**：重油重色，擅长山珍野味，代表菜：臭鳜鱼、毛豆腐、黄山炖鸽\n\n**美食体验建议**：\n\n- 品尝当地特色小吃，体验市井烟火气\n\n- 走进老字号餐厅，感受传统饮食文化\n\n- 参与美食制作体验，学习当地特色菜做法\n\n- 了解美食背后的历史故事和文化内涵\n\n### 2.5 人文摄影攻略\n\n**热门国风摄影地点推荐**：\n\n- **北京**：故宫角楼、颐和园十七孔桥、天坛祈年殿、长城\n\n- **西安**：大唐不夜城、大雁塔、城墙、兵马俑\n\n- **杭州**：西湖断桥、雷峰塔、灵隐寺、宋城\n\n- **苏州**：拙政园、留园、平江路、周庄\n\n- **宏村**：月沼、南湖、承志堂、塔川\n\n**最佳拍摄时间**：\n\n- 黄金时间：早晨 7:00-9:00，下午 16:00-18:00\n\n- 蓝调时间：日落后 30 分钟，适合拍摄夜景\n\n- 雨天：烟雨朦胧，适合拍摄江南水乡和徽派建筑\n\n**拍摄技巧**：\n\n- 构图：使用三分法、引导线、框架构图，突出主体\n\n- 光影：利用侧光和逆光，增加画面层次感和立体感\n\n- 道具：使用团扇、油纸伞、灯笼、书卷等国风道具\n\n- 穿搭：穿着汉服或新中式服装，与环境融为一体\n\n**避坑指南**：\n\n- 避开现代建筑、路灯、广告牌等破坏古风氛围的元素\n\n- 选择游客稀少的时段拍摄，避免画面中出现大量人群\n\n- 尊重当地文化和习俗，不随意拍摄宗教场所和当地居民\n\n- 遵守景区规定，不进入禁止拍摄的区域\n\n---\n\n## 第三部分：不同人群人文游定制方案\n\n### 3.1 独行旅行者\n\n**核心需求**：深度体验、自由灵活、社交互动、安全保障\n**推荐目的地**：西安、大理、泉州、凤凰、苏州\n**体验重点**：\n\n- 入住青年旅舍或特色民宿，结交志同道合的朋友\n\n- 参加当地文化活动和体验课程，深入了解当地文化\n\n- 漫步古城小巷，发现不为人知的小众景点\n\n- 品尝当地特色小吃，体验市井生活\n\n### 3.2 情侣\n\n**核心需求**：浪漫氛围、独特体验、纪念意义、私密空间\n**推荐目的地**：杭州西湖、丽江古城、大理洱海、凤凰古城、厦门鼓浪屿\n**体验重点**：\n\n- 入住浪漫主题酒店或海景民宿\n\n- 乘坐游船或缆车，欣赏美景\n\n- 拍摄情侣写真或汉服旅拍\n\n- 参与浪漫的文化活动，如放河灯、拜织女\n\n### 3.3 家庭亲子\n\n**核心需求**：寓教于乐、安全舒适、互动性强、适合儿童\n**推荐目的地**：北京、西安、上海、成都、广州\n**体验重点**：\n\n- 参观博物馆和科技馆，增长知识\n\n- 参与亲子非遗体验活动，培养孩子动手能力\n\n- 游览主题公园和动物园，增加趣味性\n\n- 选择设施完善、服务周到的亲子酒店\n\n### 3.4 老年游客\n\n**核心需求**：节奏缓慢、安全舒适、交通便利、医疗保障\n**推荐目的地**：北京、杭州、苏州、成都、桂林\n**体验重点**：\n\n- 选择交通便利、地势平坦的景点\n\n- 避免长时间步行和高强度活动\n\n- 入住靠近市中心或景区的酒店\n\n- 品尝清淡可口、营养丰富的当地美食\n\n### 3.5 摄影爱好者\n\n**核心需求**：绝佳机位、独特光影、人文风情、创作空间\n**推荐目的地**：宏村、婺源、霞浦、元阳梯田、喀什古城\n**体验重点**：\n\n- 提前了解最佳拍摄时间和机位\n\n- 早起晚归，捕捉黄金时间和蓝调时间的美景\n\n- 深入当地生活，拍摄人文纪实照片\n\n- 参加摄影团或与当地摄影师交流\n\n### 3.6 研学团队\n\n**核心需求**：知识丰富、教育意义、互动性强、安全保障\n**推荐目的地**：北京、西安、南京、曲阜、敦煌\n**体验重点**：\n\n- 参观历史文化遗址和博物馆\n\n- 邀请专家学者进行专题讲座\n\n- 开展实地考察和调研活动\n\n- 组织研学分享会和成果展示\n\n---\n\n## 第四部分：人文游预约与讲解服务指南\n\n### 4.1 2026 年最新景区预约政策\n\n**热门景区预约规则**：\n\n|景区名称|预约渠道|放票时间|提前预约天数|注意事项|\n|---|---|---|---|---|\n|故宫博物院|微信小程序 \"故宫博物院\"|提前 7 天 20:00|7 天|周一闭馆（法定节假日除外），珍宝馆、钟表馆需单独预约|\n|中国国家博物馆|微信小程序 \"国家博物馆\"|提前 7 天 17:00|7 天|周一闭馆（法定节假日除外），大件行李需寄存|\n|秦始皇兵马俑博物馆|微信小程序 \"秦始皇帝陵博物院\"|提前 7 天|7 天|刷身份证入园，可同时预约丽山园|\n|布达拉宫|微信小程序 \"布达拉宫票务预订系统\"|提前 7 天|7 天|每日限流，需提前预约，禁止携带液体|\n|敦煌莫高窟|微信小程序 \"莫高窟参观预约网\"|提前 30 天|30 天|分为 A 类票（8 个洞窟 + 数字电影）和 B 类票（4 个洞窟）|\n\n**通用预约技巧**：\n\n- 提前在小程序中添加所有参观人身份证信息，抢票时直接勾选\n\n- 设置闹钟提醒，在放票前 1-2 分钟进入小程序等待\n\n- 如遇门票售罄，可尝试在临近日期刷新，可能会有退票回流\n\n- 部分景区提供学生票、老年票等优惠票种，需携带相关证件\n\n### 4.2 讲解服务类型与选择\n\n**讲解服务类型对比**：\n\n|讲解类型|价格|优点|缺点|适用人群|\n|---|---|---|---|---|\n|人工讲解|100-500 元 / 次|讲解生动、互动性强、可定制内容|价格较高、需提前预约|家庭、团队、深度文化爱好者|\n|拼团讲解|20-50 元 / 人|价格便宜、可与其他游客拼团|讲解内容固定、互动性差|独行旅行者、预算有限的游客|\n|自助讲解机|10-30 元 / 台|价格便宜、使用方便、可反复收听|讲解生硬、缺乏互动|普通游客、时间自由的游客|\n|数字导览|免费 - 10 元|无需额外设备、可离线使用、内容丰富|需要智能手机、部分功能需联网|年轻游客、科技爱好者|\n\n**讲解服务选择建议**：\n\n- 对于历史文化底蕴深厚的景区，建议选择人工讲解\n\n- 对于普通景点，自助讲解机或数字导览即可满足需求\n\n- 选择正规渠道预约讲解服务，避免黑导\n\n- 提前了解讲解内容和时长，选择适合自己的讲解服务\n\n### 4.3 数字导览工具推荐\n\n- **官方小程序**：大多数景区都有自己的官方小程序，提供免费的语音导览服务\n\n- **云观博**：覆盖全国多家博物馆，提供 AR 导览、文物讲解、展览信息等服务\n\n- **三毛游**：提供全球景区的语音导览服务，内容丰富，讲解生动\n\n- **马蜂窝**：提供景区攻略、语音导览、门票预订等一站式服务\n\n- **百度地图 / 高德地图**：部分景区提供语音导览功能，可直接在地图上使用\n\n---\n\n## 第五部分：人文游避坑与文明游览指南\n\n### 5.1 常见骗局与陷阱\n\n**景区周边常见骗局**：\n\n- **假导游骗局**：景区门口主动搭讪的 \"免费导游\"，会带你去购物店或收费景点\n\n- **免费拍照骗局**：声称可以免费拍照，然后高价出售照片或相框\n\n- **算命消灾骗局**：自称 \"风水大师\"，以算命消灾为名骗取钱财\n\n- **高价香火骗局**：在宗教场所外兜售高价香火，寺院内通常有免费赠香处\n\n- **低价团骗局**：报价远低于成本的跟团游，会强制购物或增加自费项目\n\n**避坑方法**：\n\n- 拒绝任何主动搭讪的陌生人提供的服务\n\n- 只通过官方渠道购买门票和预约讲解服务\n\n- 不轻易相信 \"天上掉馅饼\" 的好事\n\n- 遇到骗局及时报警或向景区工作人员求助\n\n### 5.2 文物保护与文明游览规定\n\n**文物保护规定**：\n\n- 不触摸、不刻画、不损坏文物古迹\n\n- 不使用闪光灯拍摄文物，避免对文物造成损害\n\n- 不进入未开放区域，不翻越护栏\n\n- 不携带易燃易爆物品进入文物保护单位\n\n- 遵守景区的其他文物保护规定\n\n**文明游览规定**：\n\n- 遵守公共秩序，不插队、不拥挤、不大声喧哗\n\n- 爱护公共环境，不乱扔垃圾、不随地吐痰\n\n- 尊重当地文化和习俗，不做冒犯当地人的行为\n\n- 保护生态环境，不采摘花草、不破坏植被\n\n- 文明拍照，不影响他人游览\n\n### 5.3 不同场所礼仪规范\n\n**博物馆礼仪**：\n\n- 保持安静，不追逐打闹\n\n- 不触摸展品，不使用闪光灯拍照\n\n- 不携带食物和饮料进入展厅\n\n- 遵守展厅的其他规定\n\n**宗教场所礼仪**：\n\n- 穿着得体，不穿短裤、短裙、吊带衫进入\n\n- 不喧哗、不嬉笑打闹\n\n- 不随意拍摄佛像和宗教仪式\n\n- 尊重宗教信仰和习俗\n\n**古镇古村礼仪**：\n\n- 尊重当地居民的生活，不随意进入居民家中\n\n- 不随意拍摄当地居民，如需拍摄请先征得同意\n\n- 保持古镇古村的整洁，不乱扔垃圾\n\n- 遵守当地的风俗习惯\n\n---\n\n## 第六部分：预算与时间规划参考\n\n### 6.1 预算分配比例参考\n\n- **交通费用**：占总预算的 25%-35%\n\n- **住宿费用**：占总预算的 25%-35%\n\n- **餐饮费用**：占总预算的 15%-25%\n\n- **门票费用**：占总预算的 10%-15%\n\n- **体验费用**：占总预算的 10%-15%\n\n- **其他费用**：预留 10% 作为应急资金\n\n### 6.2 不同时长行程规划\n\n**2-3 天短途人文游**：\n\n- 适合目的地：周边城市、古镇、单一文化主题景区\n\n- 行程安排：每天安排 2-3 个主要景点，留出足够的时间深度体验\n\n- 预算参考：人均 1000-2500 元\n\n**4-5 天中长途人文游**：\n\n- 适合目的地：省会城市、文化名城、跨省短途游\n\n- 行程安排：每天安排 3-4 个主要景点，穿插体验项目和美食\n\n- 预算参考：人均 2000-4000 元\n\n**6-7 天长途人文游**：\n\n- 适合目的地：跨省游、文化主题线路、多城市串联游\n\n- 行程安排：每天安排 2-3 个主要景点，留出 1 天自由活动时间\n\n- 预算参考：人均 3000-6000 元\n\n**7 天以上深度人文游**：\n\n- 适合目的地：边疆地区、文化深度游线路、多省份串联游\n\n- 行程安排：节奏放缓，深入体验当地文化和生活\n\n- 预算参考：人均 5000 元以上\n\n### 6.3 淡季错峰技巧\n\n**淡季时间**：\n\n- 1-2 月（春节前后除外）\n\n- 3-4 月（除清明节和部分节日）\n\n- 11-12 月（除元旦和部分节日）\n\n**淡季优势**：\n\n- 游客稀少，体验感更好\n\n- 机票、酒店价格便宜，可节省 30%-50% 的费用\n\n- 景区门票可能有优惠\n\n- 更容易预约到热门景区和讲解服务\n\n**注意事项**：\n\n- 部分景区在淡季可能会缩短开放时间或进行维修\n\n- 部分体验项目和餐饮可能会暂停营业\n\n- 提前查询景区和酒店的开放情况，合理规划行程\n\n---\n\n## 第七部分：应急处理与实用信息\n\n### 7.1 紧急联系方式\n\n- 全国统一报警电话：110\n\n- 医疗急救电话：120\n\n- 交通事故报警：122\n\n- 旅游投诉热线：12301\n\n- 外交部全球领事保护与服务应急热线：+86-10-12308\n\n### 7.2 特殊情况处理\n\n**天气变化**：\n\n- 提前关注目的地天气情况，携带合适的衣物和雨具\n\n- 如遇恶劣天气，及时调整行程，避免前往山区、海边等危险区域\n\n- 如遇航班或火车延误，联系航空公司或铁路部门改签或退票\n\n**行程变更**：\n\n- 提前联系酒店或平台取消预订，尽量避免损失\n\n- 如遇酒店超售，要求酒店升级房型或安排附近同等级酒店\n\n- 如遇景区临时关闭，及时调整行程，选择其他景点\n\n**物品丢失**：\n\n- 如丢失身份证，可到当地派出所办理临时身份证明\n\n- 如丢失银行卡或信用卡，及时联系银行挂失\n\n- 如丢失贵重物品，及时报警并联系景区工作人员协助寻找\n\n### 7.3 常用工具推荐\n\n**出行工具**：\n\n- 携程、同程、飞猪：机票、酒店、门票预订\n\n- 12306：火车票预订\n\n- 高德地图、百度地图：导航、实时路况查询\n\n- 滴滴出行：网约车、出租车预订\n\n**文化工具**：\n\n- 云观博：博物馆 AR 导览\n\n- 三毛游：景区语音导览\n\n- 中国国家博物馆、故宫博物院官方小程序：展览信息、预约购票\n\n- 古诗文网：古诗词查询、赏析\n\n**生活工具**：\n\n- 支付宝、微信：移动支付、扫码乘车\n\n- 美团、大众点评：美食、酒店、娱乐查询预订\n\n- 携程旅行、去哪儿旅行：旅游攻略、产品预订\n\n- 天气通、墨迹天气：天气预报查询',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:46:50', '2026-06-15 14:46:50');
INSERT INTO `rag_knowledge_document`
VALUES (297, '各地避坑避雷攻略篇', '',
        '# 各地避坑避雷攻略篇\n\n## 第一部分：避坑避雷核心原则\n\n### 1.1 通用防骗铁律\n\n- **不贪小便宜**：所有低于市场价 30% 以上的产品必有陷阱\n\n- **走正规渠道**：拒绝任何主动搭讪的陌生人提供的服务\n\n- **保留所有证据**：订单截图、聊天记录、发票、照片视频缺一不可\n\n- **理性消费**：不冲动购买任何超出预算或非必需的商品\n\n- **提前做功课**：了解目的地基本物价和常见骗局类型\n\n### 1.2 风险等级划分\n\n|风险等级|特征|应对策略|\n|---|---|---|\n|**低风险**|价格虚高、服务缩水|货比三家，理性议价|\n|**中风险**|强制消费、虚假宣传|保留证据，平台投诉|\n|**高风险**|人身威胁、诈骗勒索|立即报警，寻求帮助|\n|**极高风险**|违法犯罪、人身伤害|优先保证人身安全，事后维权|\n\n---\n\n## 第二部分：交通出行避坑全指南\n\n### 2.1 城际交通避坑\n\n#### 2.1.1 机票预订陷阱\n\n- **捆绑销售**：默认勾选保险、接送机、酒店优惠券，预订时务必取消\n\n- **低价票陷阱**：标注 \"99 元特价票\"，实际不含行李额，托运费远超机票价格\n\n- **退改费陷阱**：特价票退改费高达 100%，部分平台甚至不支持退改\n\n- **里程诈骗**：声称可以代订里程票，收款后拉黑或提供假票\n\n- **虚假航班**：非正规平台发布不存在的航班信息，骗取定金\n\n**避坑方法**：\n\n- 优先在航空公司官方 APP 或小程序购票\n\n- 仔细阅读退改政策和行李额说明\n\n- 收到航班变动短信，直接拨打航空公司官方电话核实\n\n#### 2.1.2 火车票预订陷阱\n\n- **第三方加价**：抢票软件收取高额加速费，成功率与免费抢票无差异\n\n- **假票诈骗**：声称有内部票、预留票，提供伪造的电子票或纸质票\n\n- **买短补长骗局**：诱导乘客购买短途票上车，声称可以补票，实际导致无法乘车\n\n- **退票诈骗**：冒充铁路客服，以退票为由骗取银行卡信息和验证码\n\n**避坑方法**：\n\n- 只使用 12306 官方 APP 购票和候补\n\n- 不相信任何 \"内部渠道\"、\"百分百抢票成功\" 的宣传\n\n- 退票改签仅在 12306 官方平台操作\n\n#### 2.1.3 长途大巴与租车陷阱\n\n- **黑大巴**：无正规运营资质，超载严重，中途甩客或加价\n\n- **租车陷阱**：隐瞒车辆故障，还车时以 \"车辆损坏\" 为由克扣押金\n\n- **保险套路**：强制购买不必要的保险，或声称 \"全险\" 实际有很多免责条款\n\n- **异地还车费**：预订时不说明，还车时收取高额异地还车费\n\n### 2.2 市内交通避坑\n\n#### 2.2.1 出租车与网约车陷阱\n\n- **出租车绕路**：故意选择绕路路线，多收车费\n\n- **不打表收费**：一口价收费，通常是打表价格的 2-3 倍\n\n- **网约车加价**：高峰时段恶意加价，或诱导乘客取消订单私下交易\n\n- **虚假定位**：司机修改定位，显示已到达实际未到，骗取乘客取消订单\n\n- **拼车陷阱**：声称是快车，实际拼多个人，费用不变\n\n**避坑方法**：\n\n- 要求出租车打表，拒绝不打表的车辆\n\n- 使用导航软件监督路线，发现绕路及时指出\n\n- 网约车不私下交易，所有费用通过平台支付\n\n#### 2.2.2 景区交通陷阱\n\n- **观光车强制消费**：声称景区很大必须坐观光车，实际步行即可到达\n\n- **分段收费**：观光车分多段收费，全程费用远超门票价格\n\n- **黑车宰客**：景区门口黑车声称 \"直达山顶\"，实际只送到半路\n\n- **索道套路**：故意关闭步行道，强制游客乘坐索道\n\n### 2.3 机场火车站周边陷阱\n\n- **拉客住宿**：声称 \"酒店免费接送\"、\"低价房\"，实际带到偏远的黑旅馆\n\n- **黑车宰客**：不打表，一口价收费，甚至半路加价\n\n- **假安检**：冒充工作人员，以 \"安检\" 为由骗取乘客财物\n\n- **行李搬运诈骗**：主动帮忙搬运行李，然后索要高额小费\n\n- **假工作人员**：冒充机场或火车站工作人员，以 \"改签\"、\"退票\" 为由诈骗\n\n---\n\n## 第三部分：住宿预订与入住避坑\n\n### 3.1 预订阶段陷阱\n\n- **虚假宣传**：图片与实际房间严重不符，\"海景房\" 只能看到一角，\"步行 5 分钟到景点\" 是直线距离\n\n- **低价引流**：标注极低价格吸引点击，实际是无窗房、暗房或钟点房\n\n- **取消政策陷阱**：预订时显示 \"免费取消\"，实际提前 7 天以上才能免费取消\n\n- **平台刷单**：虚假好评和高评分，实际住宿体验极差\n\n- **超售骗局**：预订成功后到店被告知无房，被安排到条件差的其他酒店\n\n**避坑方法**：\n\n- 多看近期差评，重点关注卫生、服务和房间与描述不符的问题\n\n- 预订前仔细阅读取消政策和房型说明\n\n- 选择支持 \"到店付\" 或 \"免费取消\" 的酒店\n\n- 收到预订成功短信后，提前电话联系酒店确认\n\n### 3.2 入住阶段陷阱\n\n- **卫生问题**：床单被罩不更换、毛巾浴巾不干净、卫生间有异味\n\n- **隐形消费**：房间内的饮料、零食、避孕套等价格远超市场价\n\n- **安全隐患**：门锁损坏、消防设施缺失、没有防盗链\n\n- **噪音问题**：靠近电梯、马路或 KTV，夜间噪音严重影响休息\n\n- **骚扰电话**：入住后收到各种按摩、上门服务的骚扰电话\n\n**避坑方法**：\n\n- 入住时立即检查房间卫生和设施，发现问题立即要求更换房间\n\n- 房间内的付费物品使用前先看价格\n\n- 反锁房门，拉上防盗链，不要给陌生人开门\n\n### 3.3 退房阶段陷阱\n\n- **无理扣费**：以 \"弄脏床单\"、\"损坏物品\" 为由克扣押金\n\n- **押金不退**：声称 \"押金需要 3-7 个工作日退还\"，实际拖延不退\n\n- **物品损坏讹诈**：将之前客人损坏的物品归咎于现任客人\n\n- **延迟退房收费**：延迟 10 分钟就收取半天房费\n\n**避坑方法**：\n\n- 退房时让服务员当面检查房间，确认无误后再离开\n\n- 押金要求当场退还，拒绝拖延\n\n- 入住时检查房间物品是否完好，如有损坏提前告知前台\n\n---\n\n## 第四部分：餐饮消费避坑\n\n### 4.1 景区餐饮陷阱\n\n- **天价菜**：普通海鲜、家常菜标价几百上千元\n\n- **阴阳菜单**：给游客看的菜单价格高，给本地人看的价格低\n\n- **强制消费**：餐具费、茶位费、服务费不提前告知\n\n- **缺斤短两**：海鲜称重时做手脚，实际重量不足\n\n- **掉包食材**：点的活海鲜被换成死海鲜\n\n**避坑方法**：\n\n- 景区内尽量只吃简餐，正餐到市区居民区的餐馆\n\n- 点菜前确认所有菜品价格和收费项目\n\n- 海鲜称重时要求去皮，自己看秤\n\n- 保留好菜单和发票，发现问题及时投诉\n\n### 4.2 网红店陷阱\n\n- **排队造假**：雇佣水军排队，营造火爆假象\n\n- **食物与图片不符**：宣传图片精美，实际菜品卖相和味道都很差\n\n- **分量缩水**：图片上分量很足，实际分量只有一半\n\n- **价格虚高**：味道普通的菜品，因为网红效应价格翻几倍\n\n- **服务差**：顾客多，服务态度差，上菜慢\n\n**避坑方法**：\n\n- 不要盲目相信网红推荐，多看真实用户评价\n\n- 选择本地人常去的餐馆，味道正宗价格实惠\n\n- 网红店可以先点少量菜品尝试，好吃再多点\n\n### 4.3 特色美食与夜市陷阱\n\n- **假特产美食**：声称是 \"当地特色\"，实际全国都有\n\n- **以次充好**：用劣质食材制作美食，卫生条件差\n\n- **强买强卖**：尝一口就必须买，不买就不让走\n\n- **缺斤短两**：夜市小吃分量不足，价格虚高\n\n- **卫生问题**：食材不新鲜，餐具不消毒\n\n---\n\n## 第五部分：购物消费避坑\n\n### 5.1 特产购物陷阱\n\n- **假特产**：所谓的 \"当地特产\" 其实都是义乌批发的\n\n- **高价低质**：普通商品贴上 \"特产\" 标签，价格翻几倍\n\n- **强制购物**：导游带游客到购物店，不买不让走\n\n- **以次充好**：用劣质产品冒充优质特产\n\n- **虚假宣传**：声称特产有 \"保健功效\"、\"收藏价值\"\n\n**避坑方法**：\n\n- 特产优先在大型超市或正规专卖店购买\n\n- 不要在景区内和导游推荐的购物店购买特产\n\n- 购买前了解特产的正常价格和辨别方法\n\n### 5.2 纪念品购物陷阱\n\n- **义乌货泛滥**：90% 以上的景区纪念品都是义乌生产的，全国景区都一样\n\n- **天价纪念品**：普通的小饰品、工艺品标价几百上千元\n\n- **开光骗局**：声称纪念品经过 \"高僧开光\"，可以保佑平安，价格昂贵\n\n- **字画骗局**：冒充 \"著名书法家\" 现场写字，实际是印刷品\n\n- **玉石骗局**：用劣质玉石冒充和田玉、翡翠，高价出售\n\n**避坑方法**：\n\n- 不购买价格昂贵的纪念品，只买价格便宜的小物件留作纪念\n\n- 不相信任何 \"开光\"、\"收藏价值\" 的宣传\n\n- 玉石、字画等贵重物品不要在景区购买\n\n### 5.3 免税店购物陷阱\n\n- **价格虚高**：部分免税店商品价格比国内专柜还高\n\n- **假货泛滥**：尤其是奢侈品、化妆品，容易买到假货\n\n- **捆绑销售**：强制购买套装，不能单独购买单品\n\n- **退税陷阱**：声称可以退税，实际流程复杂，退税额很低\n\n- **临期商品**：将临期商品卖给游客，不告知保质期\n\n**避坑方法**：\n\n- 购物前对比国内价格，确认确实便宜再购买\n\n- 选择正规的大型免税店，保留好购物小票\n\n- 购买化妆品时检查生产日期和保质期\n\n### 5.4 直播带货购物陷阱\n\n- **虚假宣传**：声称是 \"景区直供\"、\"产地直发\"，实际是假货\n\n- **货不对板**：收到的商品与直播展示的完全不同\n\n- **售后无门**：出现问题找不到客服，无法退换货\n\n- **价格欺诈**：声称 \"全网最低价\"，实际比其他平台贵很多\n\n---\n\n## 第六部分：景区游玩避坑\n\n### 6.1 门票陷阱\n\n- **假门票**：黄牛出售假门票，无法入园\n\n- **捆绑销售**：门票捆绑观光车、索道、演出等项目，不能单独购买\n\n- **园中园收费**：大门票便宜，里面每个小景点都要单独收费\n\n- **黄牛票加价**：热门景区黄牛票加价几倍出售\n\n- **优惠票骗局**：声称可以代买优惠票，收款后拉黑\n\n**避坑方法**：\n\n- 只在景区官方平台或正规第三方平台购买门票\n\n- 仔细阅读门票包含的项目，避免捆绑消费\n\n- 优惠票携带相关证件，在景区窗口购买\n\n### 6.2 导游服务陷阱\n\n- **黑导**：无导游证，提供虚假讲解，强制购物\n\n- **强制消费**：诱导游客购买高价商品，不买就甩脸子\n\n- **虚假讲解**：编造历史故事，误导游客\n\n- **小费索要**：明示或暗示游客索要小费\n\n- **行程缩水**：缩短景点游览时间，增加购物时间\n\n**避坑方法**：\n\n- 选择正规旅行社的导游，要求查看导游证\n\n- 拒绝导游推荐的任何购物和自费项目\n\n- 发现导游违规行为，保留证据并向景区和文旅局投诉\n\n### 6.3 体验项目陷阱\n\n- **天价拍照**：景区内拍照点强制拍照，然后高价出售照片\n\n- **强制体验**：声称 \"免费体验\"，体验后要求付费\n\n- **虚假宣传**：体验项目与宣传不符，安全性无保障\n\n- **排队陷阱**：声称 \"不用排队\"，实际还是要排队很久\n\n- **安全隐患**：体验项目设备老化，没有安全保障\n\n**避坑方法**：\n\n- 体验项目前确认价格和时长，签订正规合同\n\n- 选择有资质的正规商家，检查设备是否完好\n\n- 拒绝任何 \"免费体验\" 的诱惑\n\n---\n\n## 第七部分：跟团游避坑\n\n### 7.1 低价团陷阱\n\n- **零负团费**：团费低于成本价，靠购物和自费项目赚钱\n\n- **强制购物**：每天安排多个购物店，不买不让走\n\n- **自费项目加价**：自费项目价格比市场价高 2-3 倍\n\n- **行程缩水**：景点只看外观，游览时间严重不足\n\n- **食宿降级**：承诺的三星级酒店变成招待所，团餐质量差\n\n**避坑方法**：\n\n- 不参加任何低于市场价的低价团\n\n- 仔细阅读旅游合同，明确行程、食宿、购物和自费项目\n\n- 选择有资质的正规旅行社，签订正规旅游合同\n\n### 7.2 合同陷阱\n\n- **模糊条款**：行程中的 \"车览\"、\"外观\" 实际就是不进去\n\n- **擅自变更**：旅行社擅自变更行程、住宿和导游\n\n- **免责条款**：所有责任都推给游客，旅行社不承担任何责任\n\n- **退改条款苛刻**：退团收取高额违约金，甚至不退团费\n\n**避坑方法**：\n\n- 仔细阅读合同每一条款，对模糊条款要求明确说明\n\n- 要求旅行社将口头承诺写入合同\n\n- 保留好合同和付款凭证\n\n### 7.3 出境跟团游特殊陷阱\n\n- **签证诈骗**：声称可以代办签证，收款后拉黑\n\n- **境外强制消费**：在境外购物店强制消费，不买不让回国\n\n- **换汇陷阱**：导游以 \"优惠汇率\" 换汇，实际汇率比银行低很多\n\n- **自费项目陷阱**：境外自费项目价格虚高，甚至是非法项目\n\n- **甩团**：导游在境外甩团，游客滞留当地\n\n---\n\n## 第八部分：不同人群专属避坑指南\n\n### 8.1 亲子游避坑\n\n- **儿童票陷阱**：部分景区按身高收费，实际应该按年龄收费\n\n- **亲子项目安全**：儿童游乐设施安全隐患多，家长要全程陪同\n\n- **餐饮卫生**：儿童肠胃敏感，选择卫生条件好的餐厅\n\n- **购物诱导**：景区内的儿童玩具、零食价格虚高，质量差\n\n- **行程安排**：不要安排太紧凑的行程，避免孩子过度劳累\n\n### 8.2 老年游避坑\n\n- **保健品诈骗**：导游带老人去 \"健康中心\"，高价推销保健品\n\n- **低价团陷阱**：专门针对老年人的低价团，强制购物严重\n\n- **医疗陷阱**：声称可以 \"免费体检\"，然后诱导老人看病买药\n\n- **保险诈骗**：推销高额的旅游保险，实际保障范围很小\n\n- **行程强度**：不要参加强度太大的行程，避免身体不适\n\n### 8.3 独行游避坑\n\n- **人身安全**：晚上不要单独去偏僻的地方，不要轻易相信陌生人\n\n- **社交陷阱**：不要轻易和刚认识的人去陌生的地方\n\n- **住宿安全**：选择正规的酒店或青年旅舍，反锁房门\n\n- **财物安全**：贵重物品贴身携带，不要放在显眼的地方\n\n- **行程告知**：将行程告知家人或朋友，保持联系\n\n### 8.4 情侣游避坑\n\n- **浪漫套餐陷阱**：酒店的 \"浪漫套餐\" 价格虚高，实际内容很少\n\n- **拍照套路**：景区内的情侣写真、婚纱摄影价格昂贵，效果差\n\n- **消费诱导**：导游诱导情侣购买 \"定情信物\"、\"爱情锁\" 等\n\n- **行程安排**：兼顾双方的兴趣爱好，不要只安排一个人的行程\n\n---\n\n## 第九部分：热门地区特色避坑\n\n### 9.1 国内热门地区避坑\n\n|地区|主要陷阱|避坑方法|\n|---|---|---|\n|**三亚**|海鲜宰客、出租车绕路、酒店价格虚高|海鲜去第一市场购买加工，打表或用网约车|\n|**丽江**|酒托、艳遇骗局、客栈拉客、强制消费|不要相信酒吧的 \"艳遇\"，客栈提前在网上预订|\n|**大理**|租车陷阱、银器假货、洱海游船套路|租车选择正规公司，银器去正规专卖店|\n|**西安**|假兵马俑、黑导游、回民街宰客|兵马俑只去官方景区，回民街只逛不吃|\n|**北京**|长城一日游黑团、天安门周边黑导|长城一日游选择正规旅行社，不要相信路边拉客|\n|**重庆**|洪崖洞拍照陷阱、火锅宰客、索道黄牛|洪崖洞不要找路边拍照的，火锅去居民区|\n|**成都**|宽窄巷子高价小吃、锦里纪念品陷阱|小吃去建设路、奎星楼街，纪念品不要买|\n|**厦门**|鼓浪屿船票黄牛、曾厝垵高价民宿|船票提前在官方平台购买，民宿住中山路附近|\n\n### 9.2 境外热门地区避坑\n\n|地区|主要陷阱|避坑方法|\n|---|---|---|\n|**泰国**|佛牌诈骗、人妖合影收费、出租车不打表|不要买佛牌，人妖合影先问价格，要求打表|\n|**日本**|免税店假货、药妆价格虚高、黑导游|免税店去大型连锁，药妆对比价格|\n|**韩国**|整容陷阱、免税店捆绑销售、导游回扣|整容选择正规医院，不要相信导游推荐|\n|**欧洲**|小偷多、假警察、餐厅强制小费|保管好财物，遇到警察要求出示证件先核实|\n|**东南亚**|换汇陷阱、海关索要小费、海岛宰客|换汇去银行，海关索要小费不要给|\n\n---\n\n## 第十部分：维权与应急处理\n\n### 10.1 证据保留要点\n\n- **所有交易凭证**：订单截图、付款记录、发票、收据\n\n- **沟通记录**：与商家、导游、平台的聊天记录、通话录音\n\n- **现场证据**：照片、视频、证人联系方式\n\n- **行程证明**：机票、火车票、酒店入住记录、门票\n\n### 10.2 投诉渠道与流程\n\n1. **平台投诉**：首先联系预订平台客服，要求平台介入处理\n\n2. **商家投诉**：与商家负责人沟通，要求合理赔偿\n\n3. **政府部门投诉**：\n\n    - 全国旅游投诉热线：12301\n\n    - 消费者投诉热线：12315\n\n    - 当地文旅局投诉电话\n\n    - 12345 政务服务热线\n\n4. **法律途径**：如果以上方式都无法解决，可以向法院提起诉讼\n\n### 10.3 境外维权指南\n\n- **联系中国驻外使领馆**：寻求领事保护和帮助\n\n- **当地警方报警**：遇到诈骗、盗窃、人身伤害立即报警\n\n- **联系保险公司**：如果购买了旅游保险，及时向保险公司报案\n\n- **保留所有证据**：回国后向文旅局和消费者协会投诉\n\n### 10.4 快速维权技巧\n\n- **当场解决**：发现问题立即提出，不要离开现场后再投诉\n\n- **理性沟通**：保持冷静，不要与商家发生冲突\n\n- **明确诉求**：清楚说明自己的诉求和赔偿金额\n\n- **施压平台**：如果平台处理不力，威胁向监管部门投诉',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:47:01', '2026-06-15 14:47:01');
INSERT INTO `rag_knowledge_document`
VALUES (298, '应急与实用小贴士篇', '',
        '# 应急与实用小贴士篇\n\n## 第一部分：行前应急准备\n\n### 1.1 必备应急物品清单\n\n**保命四件套（必带）**：\n\n- **防水雨衣**：比雨伞更实用，可应对暴雨、防风和临时保暖\n\n- **大容量充电宝**：20000mAh 以内可带上飞机，确保通讯畅通\n\n- **止血绷带**：含碘伏棉片、止血贴、弹性绷带的便携急救包\n\n- **应急哨子**：体积小声音大，用于求救和定位\n\n**分类物品清单**：\n\n|类别|必备物品|可选物品|\n|---|---|---|\n|**证件类**|身份证 / 护照、签证、驾驶证、银行卡|证件复印件、电子证件照、保险单|\n|**医疗类**|常用药品、晕车药、驱蚊液、防晒霜|体温计、抗过敏药、创可贴、碘伏|\n|**电子类**|手机、充电器、数据线、耳机|相机、三脚架、转换插头、U 盘|\n|**日用品**|洗漱用品、毛巾、拖鞋、纸巾|便携水壶、折叠伞、眼罩、颈枕|\n|**安全类**|防盗包、门锁报警器、手电筒|防狼喷雾、旅行门锁、行李带|\n\n### 1.2 证件准备与备份\n\n- **证件备份**：将所有证件拍照并上传至云端（如百度云、微信收藏），同时打印一份复印件与原件分开存放\n\n- **电子证件**：提前在 \"国家政务服务平台\" 小程序下载电子身份证，国内大部分酒店和景区可使用\n\n- **护照有效期**：出境游护照有效期必须超过 6 个月，否则无法入境\n\n- **签证信息**：将签证页拍照保存，同时记录签证有效期和停留天数\n\n### 1.3 保险购买指南\n\n**保险类型对比**：\n\n|保险类型|价格|保障范围|适用人群|\n|---|---|---|---|\n|**国内旅游险**|10-50 元 / 天|意外身故 / 伤残、医疗费用、行程延误|所有国内游客|\n|**境外旅游险**|50-200 元 / 天|意外身故 / 伤残、医疗费用、紧急救援、行程变更|所有境外游客|\n|**高风险运动险**|30-100 元 / 天|潜水、滑雪、登山、跳伞等高风险运动|参与高风险项目的游客|\n|**申根签证险**|100-300 元 / 次|医疗保额≥30 万欧元，覆盖整个申根区|前往申根国家的游客|\n\n**购买注意事项**：\n\n- 选择有全球紧急救援服务的保险公司\n\n- 仔细阅读保险条款，特别是免责条款\n\n- 购买后将保险单号和救援电话保存好\n\n- 出境游务必购买包含医疗转运的保险\n\n### 1.4 信息登记与告知\n\n- **领事登记**：出境游提前在 \"中国领事\"APP 进行公民登记，便于紧急情况下使领馆联系\n\n- **行程告知**：将详细行程告知家人或朋友，包括航班、酒店、联系方式\n\n- **紧急联系人**：在手机通讯录中添加 \"ICE\"(In Case of Emergency) 紧急联系人\n\n- **社交平台**：避免在社交平台实时分享行程和位置信息\n\n---\n\n## 第二部分：常见突发情况应急处理\n\n### 2.1 自然灾害应急\n\n**山洪 / 泥石流**：\n\n- **预警信号**：溪水暴涨、水质变浑、山谷异响、地面开裂\n\n- **撤离方向**：沿着山沟垂直方向向高处跑，不要顺着沟谷往下跑\n\n- **避险地点**：选择坚固的高地、大树或岩石上，避免在桥梁、陡坡、低洼处逗留\n\n- **求救方法**：使用鲜艳衣物、手电筒、哨子发出求救信号，尽量保存体力\n\n**地震**：\n\n- **室内避险**：躲在坚固的桌子下或墙角，远离玻璃窗、阳台和吊灯\n\n- **室外避险**：远离建筑物、电线杆、大树，跑到开阔地带\n\n- **被困自救**：不要大喊大叫，保存体力，用硬物敲击墙壁或管道发出信号\n\n- **灾后注意**：注意余震，不要进入受损建筑物，远离燃气管道和电线\n\n**台风 / 暴雨**：\n\n- **提前准备**：储备足够的水和食物，加固门窗，将车辆停放在高处\n\n- **室内避险**：关闭门窗，拔掉电源插头，远离窗户和阳台\n\n- **室外避险**：不要在大树、广告牌、电线杆下避雨，不要涉水行走\n\n- **积水处理**：如遇积水，不要贸然通过，特别是地下通道和低洼路段\n\n### 2.2 交通事故应急\n\n- **保持冷静**：立即停车，开启危险报警闪光灯，设置警示标志\n\n- **人员救助**：优先救助受伤人员，拨打 120 急救电话，对出血、骨折进行初步处理\n\n- **现场保护**：不要移动事故车辆和物品，拍照记录现场情况\n\n- **报警处理**：拨打 122 交通事故报警电话，同时联系保险公司和旅行社\n\n- **境外事故**：立即联系当地警方和中国驻外使领馆，寻求帮助\n\n### 2.3 人身伤害应急\n\n**外伤出血**：\n\n- **小伤口**：用干净的水冲洗伤口，涂抹碘伏，贴上创可贴\n\n- **大伤口**：用干净的纱布或毛巾按压伤口止血，抬高受伤部位高于心脏\n\n- **止血带**：如四肢大出血，可使用止血带或布条捆扎伤口近心端，每小时放松 3-5 分钟\n\n- **及时送医**：伤口较深或出血不止时，立即送往医院治疗\n\n**骨折 / 扭伤**：\n\n- **初步判断**：如出现疼痛、肿胀、畸形、活动受限等症状，可能是骨折\n\n- **固定处理**：用木板、树枝等硬物固定受伤部位，避免移动\n\n- **冷敷消肿**：扭伤后 48 小时内用冰袋冷敷，每次 15-20 分钟\n\n- **及时送医**：不要自行复位，尽快送往医院拍片检查\n\n**溺水**：\n\n- **岸上救援**：立即高声呼救，拨打救援电话，使用竹竿、树枝或浮具救援\n\n- **水中施救**：从背后接近溺水者，避免被溺水者抱住\n\n- **上岸急救**：清除口鼻异物，解开衣领和腰带，进行心肺复苏\n\n- **持续抢救**：心肺复苏要持续进行，直到专业救援人员到达\n\n### 2.4 突发疾病应急\n\n**中暑**：\n\n- **先兆中暑**：头晕、多汗、乏力、恶心，立即转移到阴凉通风处休息\n\n- **轻度中暑**：体温 38℃以上，面色潮红或苍白，心跳加快，用湿毛巾擦拭身体降温\n\n- **重度中暑**：抽搐、昏迷、休克，立即拨打 120 急救电话，冰敷大动脉降温\n\n- **预防措施**：避开 10:00-16:00 高温时段，多喝水，穿透气浅色衣物\n\n**急性肠胃炎**：\n\n- **症状**：腹泻、呕吐、腹痛、发烧\n\n- **处理方法**：卧床休息，暂时禁食，多喝淡盐水或口服补液盐防止脱水\n\n- **药物治疗**：服用蒙脱石散或黄连素片，发烧时服用退烧药\n\n- **及时送医**：症状持续不缓解或出现脱水症状时，立即送往医院\n\n**过敏反应**：\n\n- **轻微过敏**：皮肤瘙痒、皮疹，服用抗过敏药物，避免接触过敏原\n\n- **严重过敏**：呼吸困难、喉咙肿胀、血压下降，立即拨打 120 急救电话\n\n- **预防措施**：了解自己的过敏史，避免食用过敏食物，随身携带抗过敏药物\n\n### 2.5 财物丢失应急\n\n- **立即挂失**：银行卡丢失立即拨打银行客服电话挂失，手机丢失立即挂失手机号\n\n- **报警处理**：拨打 110 报警电话，向警方说明丢失物品和地点\n\n- **证件补办**：身份证丢失可到当地派出所办理临时身份证明，护照丢失联系中国驻外使领馆补办\n\n- **支付安全**：立即冻结支付宝、微信等支付账户，修改密码\n\n---\n\n## 第三部分：不同场景应急指南\n\n### 3.1 山区旅游应急\n\n- **行前准备**：查询天气预报和地质灾害预警，穿防滑登山鞋，携带登山杖和头灯\n\n- **路线选择**：走景区正规路线，不要进入未开发区域，不要单独行动\n\n- **天气变化**：如遇恶劣天气，立即下山避险，不要在山顶或大树下停留\n\n- **迷路自救**：保持冷静，原路返回，使用手机导航或指南针定位，发出求救信号\n\n- **野生动物**：不要接近或投喂野生动物，遇到熊、蛇等危险动物时慢慢后退\n\n### 3.2 海滨旅游应急\n\n- **游泳安全**：在指定区域游泳，不要单独下海，不要在酒后或空腹时游泳\n\n- **潮汐变化**：了解当地潮汐时间，避免在退潮时远海游泳，防止被潮水冲走\n\n- **海洋生物**：不要触摸水母、海胆等有毒海洋生物，如被蜇伤立即用海水冲洗\n\n- **乘船安全**：乘坐正规游船，按规定穿着救生衣，不要在船上打闹\n\n- **台风预警**：收到台风预警立即离开海边，转移到安全的内陆地区\n\n### 3.3 城市旅游应急\n\n- **交通安全**：遵守交通规则，走人行横道，不要乘坐无牌无证的 \"黑车\"\n\n- **人员密集场所**：注意保管好个人财物，避免在人多的地方停留过久\n\n- **公共场所礼仪**：遵守公共秩序，不大声喧哗，尊重当地文化和习俗\n\n- **迷路处理**：使用手机导航，或向警察、工作人员询问，不要轻易相信陌生人\n\n- **紧急疏散**：遇到紧急情况时，听从工作人员指挥，有序疏散\n\n### 3.4 境外旅游应急\n\n- **当地法规**：提前了解目的地国家的法律法规，避免因不了解法律而违法\n\n- **文化习俗**：尊重当地文化和宗教信仰，穿着得体，避免冒犯当地人\n\n- **语言沟通**：下载翻译 APP，提前学习几句当地常用语\n\n- **安全区域**：避免前往治安不好的区域，晚上尽量不要单独外出\n\n- **领事保护**：遇到紧急情况时，立即联系中国驻外使领馆寻求帮助\n\n---\n\n## 第四部分：证件与财物安全\n\n### 4.1 证件安全管理\n\n- **分开存放**：将证件和现金分开存放，不要放在同一个包或口袋里\n\n- **贴身携带**：重要证件贴身携带，不要放在托运行李或背包外侧\n\n- **酒店保管**：入住酒店时，将贵重物品存入酒店保险箱，不要放在房间内\n\n- **使用注意**：使用证件后立即收回，不要随意交给陌生人\n\n- **丢失处理**：证件丢失立即报警，并联系相关部门补办\n\n### 4.2 财物安全防范\n\n- **现金管理**：不要携带大量现金，分散存放在不同地方\n\n- **银行卡使用**：使用银行卡时遮挡密码，不要在不安全的 ATM 机上取款\n\n- **支付安全**：使用移动支付时，开启指纹或面部识别，定期检查账单\n\n- **行李安全**：乘坐交通工具时，行李不要离开视线，使用行李锁\n\n- **防盗技巧**：在人多的地方将背包背在胸前，不要边走边看手机\n\n### 4.3 数字安全保护\n\n- **VPN 使用**：出境游使用 VPN 保护网络安全，避免使用公共 WiFi 进行敏感操作\n\n- **账号安全**：开启双重认证，下载 2FA 备份代码并打印保存\n\n- **设备安全**：开启手机和电脑的 \"查找我的设备\" 功能，设置锁屏密码\n\n- **数据备份**：重要数据提前备份到云端，避免设备丢失或损坏\n\n- **隐私保护**：不要在公共电脑上登录个人账号，使用后及时退出并清除记录\n\n---\n\n## 第五部分：健康与医疗应急\n\n### 5.1 常见疾病预防\n\n- **饮食卫生**：选择卫生条件好的餐厅就餐，不吃生冷食物，不喝生水\n\n- **个人卫生**：勤洗手，使用洗手液或免洗消毒液\n\n- **疫苗接种**：根据目的地国家的要求，提前接种相关疫苗\n\n- **防蚊防虫**：使用驱蚊液，穿长袖衣裤，避免在蚊虫多的地方停留\n\n- **劳逸结合**：合理安排行程，避免过度劳累，保证充足睡眠\n\n### 5.2 药品携带指南\n\n**必备药品清单**：\n\n- **感冒药**：复方氨酚烷胺片、连花清瘟胶囊\n\n- **肠胃药**：蒙脱石散、黄连素片、奥美拉唑\n\n- **止痛药**：布洛芬、对乙酰氨基酚\n\n- **抗过敏药**：氯雷他定、西替利嗪\n\n- **外用药**：碘伏、创可贴、云南白药气雾剂\n\n- **其他**：晕车药、驱蚊液、防晒霜、眼药水\n\n**出境带药注意事项**：\n\n- 了解目的地国家的药品入境规定，禁止携带违禁药品\n\n- 携带药品时保留原包装和说明书\n\n- 如需携带特殊药品，提前请医生开具处方和英文证明\n\n- 不要携带超过个人使用量的药品\n\n### 5.3 境外就医指南\n\n- **保险联系**：就医前先联系保险公司，了解理赔流程和指定医院\n\n- **医院选择**：选择正规的公立医院或国际医院，避免去私人诊所\n\n- **语言沟通**：使用翻译 APP，或请酒店工作人员协助沟通\n\n- **费用支付**：保留好所有医疗单据和发票，以便回国后理赔\n\n- **紧急救援**：如遇紧急情况，立即拨打当地急救电话，同时联系保险公司和中国驻外使领馆\n\n---\n\n## 第六部分：实用工具与 APP 推荐\n\n### 6.1 国内旅游必备 APP\n\n|类别|APP 名称|核心功能|推荐指数|\n|---|---|---|---|\n|**交通出行**|12306|火车票预订、改签、退票|★★★★★|\n||高德地图|导航、实时路况、公交地铁查询|★★★★★|\n||滴滴出行|网约车、出租车、顺风车预订|★★★★★|\n|**住宿预订**|携程旅行|酒店、民宿、机票、门票一站式预订|★★★★★|\n||美团|本地住宿、美食、娱乐查询预订|★★★★☆|\n|**美食探店**|大众点评|餐厅推荐、用户评价、团购优惠|★★★★★|\n|**攻略参考**|马蜂窝|旅游攻略、景点介绍、用户分享|★★★★☆|\n|**实用工具**|国家政务服务平台|电子身份证、健康码、证件办理|★★★★★|\n||支付宝 / 微信|移动支付、扫码乘车、生活服务|★★★★★|\n\n### 6.2 境外旅游必备 APP\n\n|类别|APP 名称|核心功能|推荐指数|\n|---|---|---|---|\n|**导航地图**|Google Maps|全球导航、离线地图、公共交通查询|★★★★★|\n||[Maps.me](Maps.me)|纯离线导航，徒步路线详细|★★★★☆|\n|**翻译工具**|Google 翻译|拍照翻译、语音翻译、离线翻译|★★★★★|\n||有道翻译官|支持多语言翻译，离线功能强大|★★★★☆|\n|**住宿预订**|[Booking.com](https://Booking.com)|全球酒店预订，免费取消政策友好|★★★★★|\n||Airbnb|全球民宿预订，体验当地生活|★★★★☆|\n|**交通出行**|Skyscanner|全球机票比价，价格提醒|★★★★★|\n||Uber|全球网约车服务|★★★★☆|\n|**实用工具**|中国领事|领事登记、安全提醒、紧急求助|★★★★★|\n||TripIt|自动整合行程单，离线查看|★★★★☆|\n\n### 6.3 应急工具推荐\n\n- **急救 APP**：\"急救\"APP，提供各种急救知识和视频教程\n\n- **天气 APP**：\"墨迹天气\"、\"天气通\"，提供精准天气预报和灾害预警\n\n- **翻译 APP**：\"Google 翻译\"、\"有道翻译官\"，支持离线翻译\n\n- **导航 APP**：\"高德地图\"、\"Google Maps\"，支持离线导航\n\n- **求救 APP**：\"一键求救\"APP，可一键拨打紧急电话并发送位置信息\n\n---\n\n## 第七部分：各国 / 地区入境与当地法规\n\n### 7.1 2026 年最新入境政策\n\n**互免签证国家（30 天为主）**：\n\n- 新加坡、马来西亚、泰国、阿联酋、塞尔维亚、毛里求斯、斐济\n\n- 俄罗斯（至 2026 年 9 月 14 日）、巴西（2026 年 5 月 11 日起）\n\n**单方面免签国家**：\n\n- 土耳其（180 天内累计 90 天）、菲律宾（14 天，仅限马尼拉 / 宿务）\n\n- 韩国济州岛（30 天）、伊朗（21 天）\n\n**有条件免签 / 试行**：\n\n- 柬埔寨（2026 年 6 月 15 日至 10 月 15 日试行 14 天免签）\n\n**通用入境要求**：\n\n- 护照有效期≥6 个月\n\n- 持有返程机票和酒店预订单\n\n- 携带足额资金证明\n\n- 填写电子入境卡\n\n### 7.2 海关申报新规\n\n- **现金限额**：欧盟、加拿大等国家要求携带超过 1 万欧元（或等值货币）必须申报\n\n- **电子产品**：部分国家（如澳大利亚）可能要求解锁手机或电脑抽查内容\n\n- **禁止携带**：毒品、武器、易燃易爆物品、新鲜水果、肉类、种子等\n\n- **烟酒限制**：各国对烟酒的携带数量有不同限制，提前了解相关规定\n\n### 7.3 当地法规与禁忌\n\n- **新加坡**：禁止随地吐痰、乱扔垃圾、嚼口香糖，违者罚款\n\n- **泰国**：禁止对王室不敬，进入寺庙需穿着得体，脱鞋脱帽\n\n- **日本**：禁止在公共交通工具上打电话，排队时不要插队\n\n- **阿联酋**：禁止在公共场合饮酒、接吻，穿着暴露\n\n- **印度**：进入寺庙需脱鞋，不要用左手递东西或握手\n\n---\n\n## 第八部分：旅行省钱与便利技巧\n\n### 8.1 交通省钱技巧\n\n- **机票预订**：提前 3-6 周预订国内机票，提前 2-4 个月预订国际机票，周二晚上价格最低\n\n- **火车票预订**：提前 15 天在 12306 购票，使用候补功能，尝试 \"买长乘短\"\n\n- **市内交通**：购买当地交通卡或一日票，使用共享单车解决短途出行\n\n- **多人出行**：多人同行选择包车或拼车，人均成本更低\n\n- **错峰出行**：避开节假日和旅游旺季，机票和酒店价格可节省 30%-50%\n\n### 8.2 住宿省钱技巧\n\n- **提前预订**：热门景区住宿提前 1-3 个月预订，可享受早鸟价\n\n- **平台比价**：使用多个平台比价，关注平台优惠券和会员日活动\n\n- **非核心区域**：选择非核心区域的住宿，价格低 30%-50%，交通便利即可\n\n- **长住优惠**：连住 3 晚以上通常有额外折扣，长住选择短租公寓\n\n- **尾单捡漏**：关注各大平台的 \"特价尾单\" 频道，当天 18:00 后可能有特价房\n\n### 8.3 餐饮省钱技巧\n\n- **本地餐馆**：选择居民区的本地餐馆，价格实惠且味道正宗\n\n- **美食街 / 夜市**：品尝当地特色小吃，性价比高\n\n- **自己做饭**：入住带厨房的民宿或公寓，自己做饭可节省大量餐饮费用\n\n- **团购优惠**：使用美团、大众点评等平台购买团购券和代金券\n\n- **酒店早餐**：选择含早餐的酒店，早餐吃饱可节省午餐费用\n\n### 8.4 门票省钱技巧\n\n- **提前预约**：热门景区提前在官方平台预约，可享受优惠价格\n\n- **联票购买**：购买景区联票或套票，比单独购买便宜\n\n- **优惠证件**：携带学生证、老年证、军官证等优惠证件，可享受门票减免\n\n- **淡季优惠**：淡季景区门票通常有折扣，部分景区甚至免费\n\n- **免费景点**：很多城市的博物馆、公园、纪念馆都是免费开放的\n\n---\n\n## 第九部分：全球紧急联系方式\n\n### 9.1 中国国内紧急电话\n\n- 全国统一报警电话：110\n\n- 医疗急救电话：120\n\n- 交通事故报警：122\n\n- 消防报警电话：119\n\n- 旅游投诉热线：12301\n\n- 全国铁路客服：12306\n\n- 中国民航客服：95530\n\n### 9.2 中国驻外使领馆紧急电话\n\n- 外交部全球领事保护与服务应急热线：+86-10-12308\n\n- 中国驻美国大使馆：+1-202-495-2266\n\n- 中国驻日本大使馆：+81-3-3403-3388\n\n- 中国驻英国大使馆：+44-20-7299-4049\n\n- 中国驻法国大使馆：+33-1-5375-8840\n\n- 中国驻德国大使馆：+49-30-2758-8572\n\n- 中国驻澳大利亚大使馆：+61-2-6228-3999\n\n### 9.3 主要国家紧急电话\n\n|国家|报警电话|急救电话|消防电话|\n|---|---|---|---|\n|美国|911|911|911|\n|加拿大|911|911|911|\n|英国|999|999|999|\n|法国|17|15|18|\n|德国|110|112|112|\n|日本|110|119|119|\n|韩国|112|119|119|\n|泰国|191|1669|199|\n|新加坡|999|999|999|\n|澳大利亚|000|000|000|',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:47:12', '2026-06-15 14:47:12');
INSERT INTO `rag_knowledge_document`
VALUES (299, '旅行摄影入门篇', '',
        '# 旅行摄影入门篇\n\n## 第一部分：摄影基础准备\n\n### 1.1 器材选择指南\n\n|器材类型|优点|缺点|适用人群|\n|---|---|---|---|\n|**手机**|轻便便携、操作简单、随时可拍、后期方便|画质有限、暗光表现差、变焦能力弱|所有游客、摄影新手|\n|**卡片机**|轻便便携、画质比手机好、操作简单|价格较高、功能有限|追求画质的普通游客|\n|**微单/单反**|画质好、可更换镜头、功能强大|体积大、重量重、操作复杂|摄影爱好者、专业摄影师|\n|**运动相机**|防水防尘、坚固耐用、适合极限运动|画质一般、广角畸变严重|户外爱好者、极限运动爱好者|\n\n**2026年旅行相机推荐**：\n\n- **城市漫步者**：理光GR IV、富士X100VI\n\n- **户外探险家**：OM System Tough TG-7、GoPro Hero 13\n\n- **全能旅行者**：索尼A7C II、佳能EOS R8\n\n### 1.2 手机摄影基础设置\n\n- **分辨率设置**：将照片分辨率设为最高（如4000×3000以上），避免后期放大模糊\n\n- **开启九宫格构图线**：在相机设置中打开\"网格线\"，这是新手构图的\"万能辅助\"\n\n- **善用HDR模式**：拍摄明暗对比强的场景（如逆光人像、天空+地面）时，打开HDR\n\n- **锁定对焦/曝光**：长按屏幕3秒，出现\"自动曝光/自动对焦锁定\"，避免画面突然变亮/变暗\n\n- **开启RAW格式**：如果手机支持，开启RAW格式拍摄，保留更多细节，方便后期调整\n\n### 1.3 必备摄影配件\n\n- **便携三脚架**：选折叠款（巴掌大小），拍夜景、合影、长曝光必用\n\n- **迷你补光板**：用于人像补光，避免面部阴影\n\n- **手机镜头附件**：广角镜头、长焦镜头、微距镜头，拓展手机摄影能力\n\n- **清洁套装**：镜头纸、气吹，保持镜头清洁\n\n- **大容量存储卡/充电宝**：保证拍摄不中断\n\n---\n\n## 第二部分：通用摄影技巧\n\n### 2.1 构图基础技巧\n\n- **三分法构图**：将画面用两条横线和两条竖线均分为九等分，重要元素放在交叉点上或沿着线条排列\n\n- **引导线构图**：利用道路、河流、栏杆等线条引导观众的视线到主体上\n\n- **框架构图**：利用门窗、拱门、树枝等框架将主体框起来，突出主体\n\n- **对称构图**：利用水面、镜面等形成对称画面，显得稳定、和谐\n\n- **留白构图**：在画面中留出大量空白，突出主体，营造意境\n\n### 2.2 光线运用技巧\n\n|光线类型|特点|适用场景|注意事项|\n|---|---|---|---|\n|**顺光**|光线从后方照射主体，画面明亮均匀|人物肖像、建筑细节|避免正午强烈顺光导致过曝|\n|**侧光**|光线从侧面照射，突出纹理和立体感|风景、人像、静物|注意明暗对比度，可适当补光|\n|**逆光**|光线从前方照射，营造氛围感|剪影、日出日落、人像|对准暗部测光，或使用HDR|\n|**柔光**|多云、清晨黄昏的光线，柔和均匀|人像、食物、静物|最佳拍摄光线，色彩还原好|\n\n**黄金拍摄时间**：\n\n- 清晨：日出前后1小时，光线柔和温暖\n\n- 黄昏：日落前后1小时，适合拍摄剪影和人像\n\n- 避开：正午11:00-14:00，光线强烈，阴影生硬\n\n### 2.3 色彩搭配技巧\n\n- **对比色搭配**：如红与绿、蓝与橙，画面鲜艳夺目\n\n- **相近色搭配**：如蓝与绿、黄与橙，画面和谐统一\n\n- **冷暖对比**：如蓝色的天空与橙色的夕阳，画面有层次感\n\n- **低饱和度搭配**：如莫兰迪色系，画面高级有质感\n\n- **单一色系**：如黑白、蓝色系，画面简洁有力\n\n---\n\n## 第三部分：不同场景摄影技巧\n\n### 3.1 人像摄影技巧\n\n- **姿势技巧**：\n\n    - 不要正对镜头，身体侧一点，更显瘦\n\n    - 手可以放在头上、腰上、口袋里，或拿一些道具\n\n    - 抓拍自然的瞬间，如走路、回头、微笑，避免僵硬摆拍\n\n- **角度技巧**：\n\n    - 从低角度拍摄，显得腿长\n\n    - 从高角度拍摄，显得脸小\n\n    - 平视角度拍摄，最自然真实\n\n- **环境人像**：\n\n    - 将人物融入当地的环境中，如古建筑、海边、草原\n\n    - 利用当地的特色元素作为道具，如油纸伞、草帽、当地小吃\n\n- **避坑提示**：\n\n    - 不要在正午强光下拍摄人像，面部阴影重\n\n    - 不要把人物放在画面正中间，显得呆板\n\n    - 注意背景，避免背景杂乱\n\n### 3.2 风景摄影技巧\n\n- **拍摄时间**：\n\n    - 日出日落时分，光线最美，色彩最丰富\n\n    - 雨后初晴，空气清新，能见度高\n\n    - 有云的天气，天空更有层次感\n\n- **构图技巧**：\n\n    - 地平线放在上1/3或下1/3处，避免居中\n\n    - 利用前景增加画面的层次感，如石头、花草、树枝\n\n    - 寻找引导线，如道路、河流、山脉，引导视线到远方\n\n- **拍摄技巧**：\n\n    - 使用三脚架，保证画面清晰\n\n    - 拍摄全景照片，展现广阔的风景\n\n    - 利用长曝光拍摄流水、云海、星空\n\n### 3.3 美食摄影技巧\n\n- **光线**：使用自然光，靠近窗户拍摄，避免使用闪光灯\n\n- **构图**：\n\n    - 俯拍：适合拍摄餐桌全景和摆盘精致的美食\n\n    - 45度角拍摄：最常用的角度，展现美食的立体感\n\n    - 特写：拍摄美食的细节，如拉丝、流心\n\n- **道具**：使用餐具、餐巾、鲜花、背景布等道具，增加画面的美感\n\n- **技巧**：\n\n    - 趁热拍摄，食物的热气和光泽最诱人\n\n    - 适当留白，突出主体\n\n    - 保持背景简洁，避免杂乱\n\n### 3.4 建筑摄影技巧\n\n- **角度技巧**：\n\n    - 低角度拍摄，显得建筑高大雄伟\n\n    - 高角度拍摄，展现建筑的整体布局\n\n    - 平视角度拍摄，展现建筑的细节\n\n- **构图技巧**：\n\n    - 利用对称构图，展现建筑的对称美\n\n    - 利用框架构图，突出建筑的主体\n\n    - 利用线条构图，展现建筑的线条美\n\n- **拍摄技巧**：\n\n    - 拍摄建筑的倒影，如水面、镜面，增加画面的趣味性\n\n    - 拍摄建筑的夜景，灯光璀璨，非常漂亮\n\n    - 注意避开人群和杂物，保持画面简洁\n\n### 3.5 夜景摄影技巧\n\n- **必备器材**：三脚架、遥控器（或手机定时拍摄）\n\n- **相机设置**：\n\n    - 降低ISO，减少噪点\n\n    - 放慢快门速度，增加进光量\n\n    - 使用手动模式，根据实际情况调整参数\n\n- **拍摄技巧**：\n\n    - 拍摄城市夜景，选择制高点，如高楼、山顶\n\n    - 拍摄车流光轨，使用长曝光\n\n    - 拍摄星空，选择光污染少的地方，使用长曝光和高ISO\n\n- **避坑提示**：\n\n    - 不要使用闪光灯，会破坏夜景的氛围\n\n    - 注意安全，不要在危险的地方拍摄\n\n---\n\n## 第四部分：旅行摄影避坑指南\n\n### 4.1 常见拍摄误区\n\n- **只拍大景不拍细节**：旅行不仅有壮丽的风景，还有很多有趣的细节，如当地的手工艺品、特色小吃、建筑细节\n\n- **过度依赖滤镜**：滤镜只是辅助，前期拍摄才是最重要的，不要过度使用滤镜导致画面失真\n\n- **盲目跟风打卡**：不要只拍网红打卡点，多发现一些小众的美景\n\n- **不注意背景**：背景杂乱会严重影响照片的质量，拍摄前要注意观察背景\n\n- **不检查相机设置**：拍摄前要检查相机的设置，避免因为设置错误导致照片报废\n\n### 4.2 人文摄影注意事项\n\n- **尊重他人**：拍摄当地居民前要先征得同意，不要偷拍\n\n- **尊重当地文化**：不要在禁止拍照的地方拍照，不要拍摄宗教仪式和敏感内容\n\n- **保持距离**：不要离拍摄对象太近，保持适当的距离\n\n- **自然真实**：拍摄人文照片要自然真实，不要摆拍\n\n- **分享照片**：如果可以，将照片分享给被拍摄者，这是一种很好的交流方式\n\n### 4.3 安全注意事项\n\n- **人身安全**：不要在危险的地方拍摄，如悬崖、马路中间、未开发区域\n\n- **财物安全**：拍摄时要注意保管好自己的财物，避免被盗\n\n- **设备安全**：保护好自己的相机和手机，避免摔落、进水、被盗\n\n- **天气安全**：注意天气变化，避免在恶劣天气下拍摄\n\n---\n\n## 第五部分：后期处理基础\n\n### 5.1 常用后期软件\n\n- **手机端**：醒图、Snapseed、Lightroom Mobile、VSCO\n\n- **电脑端**：Photoshop、Lightroom Classic、Capture One\n\n### 5.2 基础后期步骤\n\n1. **调整曝光**：调整亮度、对比度、高光、阴影，让画面曝光准确\n\n2. **调整色彩**：调整色温、色调、饱和度、自然饱和度，让画面色彩自然\n\n3. **调整细节**：调整清晰度、锐化、降噪，让画面更清晰\n\n4. **裁剪构图**：裁剪掉多余的部分，重新构图\n\n5. **添加滤镜**：适当添加滤镜，增加画面的氛围感\n\n### 5.3 后期处理原则\n\n- **适度原则**：后期处理要适度，不要过度调整，保持照片的自然真实\n\n- **统一风格**：一组照片的风格要统一，色调和滤镜要一致\n\n- **突出主体**：通过后期处理突出照片的主体，让观众一眼就能看到重点\n\n- **保留细节**：不要因为后期处理丢失照片的细节，尤其是高光和阴影部分\n\n---\n\n## 第六部分：实用工具推荐\n\n### 6.1 摄影学习工具\n\n- **小红书/抖音**：摄影技巧分享、作品欣赏\n\n- **图虫/500px**：专业摄影社区，作品欣赏和交流\n\n- **B站/YouTube**：摄影教程视频\n\n- **摄影书籍**：《纽约摄影学院教材》、《手机摄影从小白到大师》\n\n### 6.2 摄影工具APP\n\n- **醒图**：人像修图、滤镜、拼图\n\n- **Snapseed**：专业手机修图软件，功能强大\n\n- **Lightroom Mobile**：专业调色软件，可同步电脑端\n\n- **VSCO**：胶片滤镜，风格独特\n\n- **全景相机**：拍摄全景照片\n\n### 6.3 其他实用工具\n\n- **天气APP**：查询日出日落时间、天气情况\n\n- **指南针APP**：确定方向，寻找最佳拍摄角度\n\n- **地图APP**：寻找拍摄地点，规划拍摄路线\n\n- **云存储**：备份照片，避免丢失',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:47:25', '2026-06-15 14:47:25');
INSERT INTO `rag_knowledge_document`
VALUES (300, '旅行预算管理篇', '',
        '# 旅行预算管理篇\n\n## 文档说明\n\n- **版本**：V1.0（2026 年 6 月更新）\n\n- **适用范围**：全球所有旅游目的地通用\n\n- **适配人群**：独行、情侣、家庭、亲子、商务、老年、研学团队\n\n- **RAG 检索优化**：按费用类别语义分块，关键省钱技巧加粗标注，包含2026年最新消费趋势和省钱工具\n\n- **更新频率**：每季度更新一次各地消费水平和最新省钱技巧\n\n---\n\n## 第一部分：预算制定核心原则\n\n### 1.1 预算分配黄金比例\n\n|费用类别|占总预算比例|说明|\n|---|---|---|\n|**交通费用**|30%-40%|包括机票、火车票、汽车票、市内交通等|\n|**住宿费用**|30%-40%|包括酒店、民宿、青旅等住宿费用|\n|**餐饮费用**|15%-25%|包括一日三餐、零食、饮料等|\n|**门票与体验费用**|10%-15%|包括景点门票、演出票、体验项目等|\n|**购物费用**|5%-10%|包括特产、纪念品、个人购物等|\n|**应急资金**|10%|预留作为突发情况的备用资金|\n\n### 1.2 预算制定三步法\n\n1. **确定总预算**：根据自己的经济能力和旅行时长确定总预算\n\n2. **分解费用类别**：按照黄金比例将总预算分解到各个费用类别\n\n3. **细化每日预算**：将每个费用类别的预算分解到每天，方便控制支出\n\n### 1.3 预算制定注意事项\n\n- **留有余地**：预算不要制定得太满，预留一定的弹性空间\n\n- **参考当地消费水平**：提前了解目的地的消费水平，合理制定预算\n\n- **考虑淡旺季差异**：旺季的交通、住宿、门票价格通常比淡季高30%-50%\n\n- **包含所有费用**：不要遗漏任何可能的费用，如签证费、保险费、小费等\n\n---\n\n## 第二部分：各项费用预算方法\n\n### 2.1 交通费用预算\n\n- **机票费用**：\n\n    - 提前3-6周预订国内机票，提前2-4个月预订国际机票\n\n    - 周二、周三出发的航班价格通常比周五、周六便宜20%-30%\n\n    - 使用比价工具对比不同航空公司和平台的价格\n\n    - 关注航空公司的促销活动和会员日\n\n- **火车费用**：\n\n    - 提前15天在12306购票，使用候补功能\n\n    - 尝试\"买长乘短\"或\"买短补长\"的技巧\n\n    - 选择夕发朝至的火车，节省一晚住宿费\n\n- **市内交通费用**：\n\n    - 购买当地交通卡或一日票，比单次购票便宜\n\n    - 使用共享单车解决短途出行\n\n    - 多人同行选择打车或包车，人均成本更低\n\n### 2.2 住宿费用预算\n\n- **住宿类型选择**：\n\n    - 经济型连锁酒店：100-300元/晚，适合预算有限的游客\n\n    - 中端商务酒店：300-600元/晚，适合家庭和商务游客\n\n    - 民宿：200-800元/晚，适合喜欢体验当地生活的游客\n\n    - 青年旅舍：50-150元/床位，适合独行游客和背包客\n\n- **预订技巧**：\n\n    - 提前1-3个月预订热门景区住宿，享受早鸟价\n\n    - 对比多个平台的价格，关注平台优惠券和会员日活动\n\n    - 选择非核心区域的住宿，价格低30%-50%\n\n    - 连住3晚以上通常有额外折扣\n\n### 2.3 餐饮费用预算\n\n- **餐饮类型选择**：\n\n    - 本地餐馆：人均30-80元，味道正宗，性价比高\n\n    - 美食街/夜市：人均20-50元，适合品尝当地小吃\n\n    - 酒店早餐：通常包含在房费内，节省早餐费用\n\n    - 自己做饭：入住带厨房的民宿，自己做饭可节省50%的餐饮费用\n\n- **省钱技巧**：\n\n    - 选择居民区的餐馆，避开景区和商业区\n\n    - 使用美团、大众点评等平台购买团购券和代金券\n\n    - 早餐吃饱，午餐吃好，晚餐简单\n\n    - 多人拼餐，既可以品尝更多美食，又可以节省费用\n\n### 2.4 门票与体验费用预算\n\n- **门票省钱技巧**：\n\n    - 提前在官方平台预约门票，享受优惠价格\n\n    - 购买景区联票或套票，比单独购买便宜\n\n    - 携带学生证、老年证、军官证等优惠证件，可享受门票减免\n\n    - 关注景区的免费开放日和淡季优惠\n\n- **体验项目预算**：\n\n    - 选择性价比高的体验项目，避免不必要的消费\n\n    - 对比不同商家的价格和评价，选择正规商家\n\n    - 不要相信路边拉客的低价体验项目，容易被宰\n\n### 2.5 其他费用预算\n\n- **购物费用**：只购买自己真正需要的东西，避免冲动消费\n\n- **保险费用**：购买旅游保险，费用通常为总预算的1%-2%\n\n- **签证费用**：根据目的地国家的签证政策提前预算\n\n- **小费费用**：了解目的地的小费文化，提前预算小费支出\n\n---\n\n## 第三部分：省钱技巧大全\n\n### 3.1 交通省钱技巧\n\n- **错峰出行**：避开节假日和旅游旺季，机票和酒店价格可节省30%-50%\n\n- **选择红眼航班或凌晨车次**：价格通常比白天便宜很多\n\n- **使用里程积分兑换机票**：积累航空公司的里程积分，可兑换免费机票\n\n- **拼车/顺风车**：使用滴滴顺风车、哈啰顺风车等平台，长途出行更便宜\n\n- **步行/骑行**：短距离出行选择步行或骑行，既省钱又锻炼身体\n\n### 3.2 住宿省钱技巧\n\n- **选择青旅或床位房**：适合独行游客，价格便宜，还能结交朋友\n\n- **入住短租公寓**：长住选择短租公寓，有厨房可自己做饭，性价比高\n\n- **关注尾单和限时秒杀**：各大平台经常有特价尾单和限时秒杀活动\n\n- **使用会员积分兑换免费房晚**：注册酒店集团会员，积分可兑换免费房晚\n\n- **反向预订**：先预订可免费取消的房间，临近日期再看是否降价\n\n### 3.3 餐饮省钱技巧\n\n- **吃早餐**：酒店的早餐通常很丰盛，吃饱早餐可以节省午餐费用\n\n- **去菜市场买菜自己做饭**：入住带厨房的民宿，自己做饭既卫生又便宜\n\n- **吃当地小吃**：当地小吃既正宗又便宜，比大餐更有特色\n\n- **使用优惠券和团购**：使用美团、大众点评等平台的优惠券和团购\n\n- **避免在景区内吃饭**：景区内的餐馆价格高且味道一般\n\n### 3.4 门票省钱技巧\n\n- **提前预约**：热门景区提前预约，可享受优惠价格\n\n- **购买旅游年卡**：如果经常旅游，购买当地的旅游年卡更划算\n\n- **关注官方公众号**：景区官方公众号经常会有优惠活动和免费门票\n\n- **参加景区活动**：景区经常会举办各种活动，有机会获得免费门票\n\n- **逃票不可取**：不要尝试逃票，一旦被发现会被罚款\n\n### 3.5 购物省钱技巧\n\n- **货比三家**：不要急于购买，对比不同商家的价格\n\n- **砍价**：在本地市场和小店可以适当砍价\n\n- **不要在景区购物**：景区内的商品价格高且质量差\n\n- **购买实用的东西**：只购买自己真正需要的东西，避免冲动消费\n\n- **使用信用卡优惠**：使用信用卡购物，可享受积分和返现优惠\n\n---\n\n## 第四部分：预算控制与记账\n\n### 4.1 预算控制方法\n\n- **每日记账**：记录每天的支出，了解自己的消费情况\n\n- **设置消费上限**：为每个费用类别设置每日消费上限，避免超支\n\n- **使用现金支付**：使用现金支付可以更好地控制支出，避免过度消费\n\n- **定期复盘**：每天或每周复盘自己的支出情况，及时调整预算\n\n- **避免冲动消费**：购物前先冷静思考，是否真的需要这个东西\n\n### 4.2 记账工具推荐\n\n- **随手记**：功能强大，操作简单，支持多种账本\n\n- **鲨鱼记账**：界面简洁，适合新手使用\n\n- **挖财**：专业的记账软件，支持预算管理和财务分析\n\n- **支付宝/微信记账**：自动同步支付记录，方便快捷\n\n- **Excel/表格**：手动记账，适合喜欢自己整理数据的人\n\n### 4.3 超支处理方法\n\n- **分析超支原因**：找出超支的具体原因，是预算制定不合理还是消费失控\n\n- **调整后续预算**：根据超支情况调整后续的预算，减少不必要的支出\n\n- **削减非必要开支**：削减购物、娱乐等非必要开支，弥补超支的部分\n\n- **增加收入**：如果可能，通过兼职等方式增加收入，弥补超支\n\n- **接受现实**：如果已经超支，不要过于自责，下次注意即可\n\n---\n\n## 第五部分：应急预算管理\n\n### 5.1 应急资金的重要性\n\n- 应对突发情况，如交通延误、身体不适、物品丢失等\n\n- 避免因为突发情况导致旅行中断\n\n- 增加旅行的安全感\n\n### 5.2 应急资金的额度\n\n- 通常为总预算的10%-15%\n\n- 长途旅行和境外旅行可适当增加应急资金的额度\n\n- 应急资金应单独存放，不要轻易动用\n\n### 5.3 应急资金的使用原则\n\n- 只用于紧急情况，不要用于日常消费\n\n- 使用后及时记录，了解资金的使用情况\n\n- 如果旅行结束后应急资金没有用完，可以留作下次旅行的资金\n\n---\n\n## 第六部分：实用工具推荐\n\n### 6.1 比价工具\n\n- **Google Flights**：全球机票比价，价格趋势分析\n\n- **Skyscanner**：全球机票、酒店、租车比价\n\n- **Booking.com**：全球酒店比价，免费取消\n\n- **什么值得买**：商品比价和优惠券推荐\n\n- **慢慢买**：历史价格查询和比价\n\n### 6.2 省钱工具\n\n- **支付宝/微信**：移动支付，经常有优惠活动\n\n- **美团/大众点评**：团购、优惠券、外卖\n\n- **携程/飞猪**：机票、酒店、门票预订，经常有促销活动\n\n- **闲鱼**：购买二手物品，出售闲置物品\n\n- **各大银行APP**：信用卡优惠、积分兑换\n\n### 6.3 记账工具\n\n- **随手记**：专业记账软件，功能强大\n\n- **鲨鱼记账**：简单易用，适合新手\n\n- **挖财**：财务管理，预算分析\n\n- **Excel/Numbers**：手动记账，自定义表格\n',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:47:36', '2026-06-15 14:47:36');
INSERT INTO `rag_knowledge_document`
VALUES (301, '特殊人群旅行指南篇', '',
        '# 特殊人群旅行指南篇\n\n## 第一部分：亲子游全攻略\n\n### 1.1 亲子游核心原则\n\n- **节奏慢一点**：每天只安排1个核心项目，预留1-2小时午休时间\n\n- **避开暴晒雷区**：优先选树荫多、有室内场馆、气候凉爽的地方\n\n- **兼顾全员适配**：景点要娃喜欢，老人能轻松逛，饮食清淡不刺激\n\n- **安全第一**：时刻关注孩子的安全，避免去危险的地方\n\n- **寓教于乐**：在旅行中让孩子学习知识，增长见识\n\n### 1.2 不同年龄段亲子游目的地推荐\n\n|年龄段|特点|推荐目的地|推荐活动|\n|---|---|---|---|\n|**0-3岁**|体力差、需要午睡、对新鲜事物好奇|三亚、青岛、厦门、珠海长隆|海边玩沙、海洋馆、动物园|\n|**4-6岁**|精力旺盛、喜欢互动、开始学习知识|上海迪士尼、广州长隆、成都、西安|主题乐园、科技馆、自然博物馆|\n|**7-12岁**|有一定的自理能力、喜欢探索、对历史文化感兴趣|北京、南京、杭州、敦煌|历史古迹、科技馆、研学旅行|\n|**13-18岁**|有自己的想法、喜欢独立、对世界充满好奇|云南、西藏、新疆、国外|户外探险、文化体验、国际交流|\n\n### 1.3 亲子游必备物品清单\n\n- **证件类**：孩子的身份证或户口本、出生证明、疫苗本\n\n- **衣物类**：多带几套换洗衣物、外套、睡衣、泳衣、防晒衣\n\n- **用品类**：奶瓶、奶粉、辅食、餐具、水杯、纸尿裤、湿巾、纸巾\n\n- **药品类**：退烧药、感冒药、肠胃药、创可贴、碘伏、驱蚊液\n\n- **娱乐类**：玩具、绘本、平板电脑、耳机\n\n- **其他类**：婴儿车、背带、儿童安全座椅、防晒帽、太阳镜\n\n### 1.4 亲子游住宿与餐饮\n\n- **住宿选择**：\n\n    - 优先选择亲子友好型酒店，有儿童乐园、儿童泳池、儿童餐等设施\n\n    - 选择家庭房或连通房，空间更大，更方便照顾孩子\n\n    - 选择靠近核心景点或交通便利的酒店，减少路上的时间\n\n- **餐饮选择**：\n\n    - 选择有儿童餐的餐馆，饮食清淡易消化\n\n    - 注意饮食卫生，避免给孩子吃生冷食物和辛辣食物\n\n    - 随身携带一些孩子喜欢的零食和水，避免孩子饿肚子\n\n### 1.5 亲子游安全注意事项\n\n- **人身安全**：\n\n    - 时刻看好孩子，不要让孩子离开自己的视线\n\n    - 给孩子佩戴防走失手环，上面写上家长的联系方式\n\n    - 教孩子记住家长的姓名、电话和家庭住址\n\n    - 避免去人多拥挤的地方，防止孩子走失\n\n- **健康安全**：\n\n    - 提前了解目的地的疫情和疾病情况，做好预防措施\n\n    - 随身携带常用药品，孩子生病时及时就医\n\n    - 注意饮食卫生，避免食物中毒\n\n    - 做好防晒和防蚊措施，避免孩子晒伤和被蚊虫叮咬\n\n---\n\n## 第二部分：老年游全攻略\n\n### 2.1 老年游核心原则\n\n- **慢节奏**：行程安排要宽松，每天步行量控制在8000步以内\n\n- **安全第一**：选择安全、成熟的旅游目的地，避免去偏远和危险的地方\n\n- **舒适为主**：选择舒适的交通和住宿，避免过度劳累\n\n- **健康第一**：根据自己的身体状况安排行程，如有不适及时休息或就医\n\n- **结伴而行**：最好和家人或朋友一起出行，互相照顾\n\n### 2.2 老年游目的地推荐\n\n- **休闲度假型**：三亚、厦门、青岛、威海、北海\n\n- **文化历史型**：北京、西安、南京、洛阳、杭州\n\n- **自然风光型**：桂林、黄山、张家界、九寨沟、千岛湖\n\n- **适老专列**：各地银发旅游专列，串联多个景点，车随人走\n\n### 2.3 老年游必备物品清单\n\n- **证件类**：身份证、老年证、医保卡、护照（如有）\n\n- **药品类**：常用药品、降压药、降糖药、心脏病药、急救药\n\n- **衣物类**：宽松舒适的衣物、软底防滑鞋、保暖外套、帽子、围巾、手套\n\n- **用品类**：保温杯、老花镜、放大镜、手电筒、充电宝、拐杖\n\n- **其他类**：家人的联系方式、病历本、保险单\n\n### 2.4 老年游交通与住宿\n\n- **交通选择**：\n\n    - 优先选择飞机或高铁，避免长途汽车和火车硬座\n\n    - 选择白天的航班或车次，避免夜间出行\n\n    - 选择靠过道的座位，方便起身活动\n\n    - 乘坐银发旅游专列，设施更适老，服务更周到\n\n- **住宿选择**：\n\n    - 选择有电梯、靠近地铁站、周边有医院的酒店\n\n    - 选择低楼层的房间，避免爬楼梯\n\n    - 选择有24小时热水、空调、防滑地板的房间\n\n    - 提前告知酒店自己的特殊需求，如需要加床、枕头等\n\n### 2.5 老年游健康与安全注意事项\n\n- **健康注意事项**：\n\n    - 出行前进行一次全面的体检，确保身体状况适合旅行\n\n    - 随身携带常用药品和病历本，按时服药\n\n    - 注意劳逸结合，避免过度劳累\n\n    - 注意饮食卫生，不吃生冷食物和油腻食物\n\n    - 保持良好的心态，不要因为小事生气\n\n- **安全注意事项**：\n\n    - 不要单独行动，最好和家人或朋友一起出行\n\n    - 不要相信陌生人的话，避免上当受骗\n\n    - 不要参加高风险的活动，如登山、漂流、潜水等\n\n    - 随身携带家人的联系方式，遇到紧急情况及时联系家人\n\n    - 购买旅游保险，保障自己的权益\n\n---\n\n## 第三部分：独行游全攻略\n\n### 3.1 独行游核心原则\n\n- **安全第一**：时刻注意自己的人身和财物安全\n\n- **灵活自由**：根据自己的兴趣和节奏安排行程\n\n- **勇敢尝试**：尝试新的事物，结交新的朋友\n\n- **提前准备**：提前做好攻略，了解目的地的情况\n\n- **保持联系**：定期和家人朋友联系，告知自己的行程\n\n### 3.2 独行游目的地推荐\n\n- **城市休闲型**：上海、杭州、成都、重庆、西安\n\n- **文艺清新型**：厦门、大理、丽江、苏州、乌镇\n\n- **户外探险型**：黄山、张家界、稻城亚丁、青海湖\n\n- **境外安全型**：日本、韩国、新加坡、泰国、马来西亚\n\n### 3.3 独行游必备物品清单\n\n- **证件类**：身份证、护照、驾驶证、银行卡\n\n- **安全类**：防盗包、门锁报警器、手电筒、哨子、防狼喷雾\n\n- **电子类**：手机、充电器、充电宝、耳机、相机\n\n- **日用品**：洗漱用品、毛巾、拖鞋、纸巾、湿巾\n\n- **药品类**：常用药品、创可贴、碘伏、晕车药\n\n### 3.4 独行游住宿与交通\n\n- **住宿选择**：\n\n    - 优先选择正规的酒店或连锁酒店，安全有保障\n\n    - 选择位置好、交通便利的酒店，避免住在偏僻的地方\n\n    - 选择有24小时前台和监控的酒店\n\n    - 入住时反锁房门，拉上防盗链，不要给陌生人开门\n\n- **交通选择**：\n\n    - 优先选择公共交通或正规的网约车\n\n    - 不要乘坐无牌无证的黑车\n\n    - 晚上尽量不要单独外出，如需外出选择人流量大的地方\n\n    - 乘坐网约车时，分享行程给家人朋友，核对车辆信息\n\n### 3.5 独行游安全注意事项\n\n- **人身安全**：\n\n    - 不要在晚上单独去偏僻的地方\n\n    - 不要轻易相信陌生人，不要和刚认识的人去陌生的地方\n\n    - 不要喝陌生人给的饮料和食物\n\n    - 随身携带防狼喷雾或哨子，遇到危险时及时求救\n\n- **财物安全**：\n\n    - 贵重物品贴身携带，不要放在背包外侧或托运行李中\n\n    - 不要在公共场所露富，避免引起小偷的注意\n\n    - 使用防盗包，将背包背在胸前\n\n    - 银行卡和身份证分开存放，不要将密码告诉任何人\n\n---\n\n## 第四部分：情侣游全攻略\n\n### 4.1 情侣游核心原则\n\n- **浪漫氛围**：选择浪漫的目的地和活动，增加感情\n\n- **共同体验**：一起尝试新的事物，创造美好的回忆\n\n- **互相包容**：尊重对方的兴趣和意见，互相照顾\n\n- **预算合理**：根据双方的经济能力制定预算，避免因为钱产生矛盾\n\n- **留下纪念**：拍照、写日记、购买纪念品，记录旅行的美好瞬间\n\n### 4.2 情侣游目的地推荐\n\n- **浪漫海滨型**：三亚、厦门、青岛、大连、马尔代夫\n\n- **古镇水乡型**：乌镇、周庄、西塘、凤凰、丽江\n\n- **城市时尚型**：上海、香港、深圳、成都、重庆\n\n- **户外探险型**：稻城亚丁、西藏、青海湖、新疆\n\n### 4.3 情侣游必备物品清单\n\n- **证件类**：身份证、护照、驾驶证、银行卡\n\n- **衣物类**：情侣装、漂亮的衣服、泳衣、防晒衣\n\n- **用品类**：相机、三脚架、自拍杆、充电宝、防晒霜\n\n- **药品类**：常用药品、创可贴、晕车药、驱蚊液\n\n- **浪漫道具**：蜡烛、鲜花、巧克力、情侣手链\n\n### 4.4 情侣游住宿与活动\n\n- **住宿选择**：\n\n    - 选择浪漫主题酒店或海景民宿\n\n    - 选择有落地窗、阳台、浴缸的房间\n\n    - 选择靠近景点或市中心的酒店，方便出行\n\n- **推荐活动**：\n\n    - 看日出日落\n\n    - 海边散步\n\n    - 情侣写真\n\n    - 一起做饭\n\n    - 看电影\n\n    - 泡温泉\n\n    - 放孔明灯\n\n    - 写许愿牌\n\n### 4.5 情侣游注意事项\n\n- **提前沟通**：提前沟通好行程、预算和住宿，避免产生矛盾\n\n- **互相照顾**：在旅行中互相照顾，关心对方的身体和情绪\n\n- **不要吵架**：即使有矛盾也不要在旅行中吵架，影响旅行心情\n\n- **留下纪念**：多拍照、多记录，留下美好的回忆\n\n- **享受当下**：放下工作和生活的烦恼，好好享受二人世界\n\n---\n\n## 第五部分：商务游全攻略\n\n### 5.1 商务游核心原则\n\n- **高效便捷**：行程安排要紧凑高效，节省时间\n\n- **专业得体**：穿着专业得体，言行举止符合商务礼仪\n\n- **安全第一**：注意人身和财物安全，保护商业机密\n\n- **劳逸结合**：在工作之余适当放松，缓解工作压力\n\n- **提前准备**：提前做好准备工作，确保商务活动顺利进行\n\n### 5.2 商务游必备物品清单\n\n- **证件类**：身份证、护照、名片、邀请函\n\n- **服装类**：西装、衬衫、领带、皮鞋、休闲装\n\n- **电子类**：笔记本电脑、手机、充电器、充电宝、U盘\n\n- **办公用品**：笔、笔记本、文件夹、计算器\n\n- **其他类**：常用药品、洗漱用品、剃须刀、香水\n\n### 5.3 商务游交通与住宿\n\n- **交通选择**：\n\n    - 优先选择直飞航班，节省时间\n\n    - 选择商务舱或头等舱，休息更好\n\n    - 提前预订接送机服务，避免耽误时间\n\n    - 在目的地选择打车或租车，出行更方便\n\n- **住宿选择**：\n\n    - 选择靠近商务活动地点的酒店，节省通勤时间\n\n    - 选择有会议室、商务中心的酒店，方便办公\n\n    - 选择服务好、设施完善的高端酒店，提升商务形象\n\n    - 提前告知酒店自己的商务需求，如需要传真、打印等服务\n\n### 5.4 商务游注意事项\n\n- **商务礼仪**：\n\n    - 穿着专业得体，言行举止大方\n\n    - 准时参加商务活动，不要迟到\n\n    - 尊重对方的文化和习俗\n\n    - 交换名片时双手递接，认真阅读对方的名片\n\n- **工作准备**：\n\n    - 提前了解对方公司的情况和商务活动的内容\n\n    - 准备好相关的资料和演示文稿\n\n    - 提前和对方沟通好商务活动的流程和细节\n\n- **安全注意事项**：\n\n    - 注意人身和财物安全\n\n    - 保护商业机密，不要在公共场所谈论商业内容\n\n    - 不要接受陌生人的礼物和宴请\n\n    - 遵守当地的法律法规和商务惯例\n\n---\n\n## 第六部分：残障人士旅行指南\n\n### 6.1 残障人士旅行核心原则\n\n- **提前规划**：提前了解目的地的无障碍设施和服务\n\n- **选择合适的目的地**：选择无障碍设施完善的目的地\n\n- **结伴而行**：最好和家人或朋友一起出行，互相照顾\n\n- **提前联系**：提前联系酒店、景点、交通部门，告知自己的特殊需求\n\n- **保持乐观**：保持乐观的心态，享受旅行的乐趣\n\n### 6.2 无障碍设施完善的目的地推荐\n\n- **国内**：北京、上海、广州、深圳、杭州\n\n- **境外**：日本、韩国、新加坡、美国、欧洲\n\n### 6.3 残障人士旅行必备物品清单\n\n- **证件类**：身份证、残疾证、医保卡\n\n- **辅助器具**：轮椅、拐杖、助听器、盲人杖\n\n- **药品类**：常用药品、急救药\n\n- **用品类**：保温杯、防滑垫、靠垫、毛毯\n\n- **其他类**：家人的联系方式、病历本\n\n### 6.4 残障人士旅行交通与住宿\n\n- **交通选择**：\n\n    - 提前联系航空公司或铁路部门，申请无障碍服务\n\n    - 选择有无障碍设施的交通工具\n\n    - 在目的地选择无障碍出租车或专车\n\n- **住宿选择**：\n\n    - 选择有无障碍房间的酒店\n\n    - 选择有电梯、无障碍卫生间的酒店\n\n    - 提前告知酒店自己的特殊需求\n\n### 6.5 残障人士旅行注意事项\n\n- **提前联系**：提前联系酒店、景点、交通部门，告知自己的特殊需求\n\n- **了解无障碍设施**：提前了解目的地的无障碍设施情况\n\n- **结伴而行**：最好和家人或朋友一起出行，互相照顾\n\n- **购买保险**：购买旅游保险，保障自己的权益\n\n- **保持联系**：定期和家人朋友联系，告知自己的行程',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:47:45', '2026-06-15 14:47:45');
INSERT INTO `rag_knowledge_document`
VALUES (302, '礼仪与穿搭指南篇', '',
        '# 礼仪与穿搭指南篇\n\n## 第一部分：通用旅行礼仪核心原则\n\n### 1.1 基本行为准则\n\n- **尊重当地文化**：入乡随俗，提前了解目的地的宗教信仰、风俗习惯和禁忌\n\n- **保持公共秩序**：不插队、不喧哗、不追逐打闹，遵守当地法律法规\n\n- **爱护公共环境**：不乱扔垃圾、不随地吐痰、不破坏文物古迹和自然景观\n\n- **尊重他人隐私**：不随意拍摄当地居民，如需拍摄请先征得同意\n\n- **文明礼貌**：使用礼貌用语，微笑待人，主动帮助有需要的人\n\n### 1.2 礼仪重要性与后果\n\n|礼仪等级|违规后果|注意事项|\n|---|---|---|\n|**一级（严重禁忌）**|可能触犯法律、被驱逐出境、人身安全受威胁|涉及宗教、政治、民族等敏感问题|\n|**二级（重要禁忌）**|可能引起当地人强烈反感、被拒绝服务|涉及当地传统习俗和道德观念|\n|**三级（一般礼仪）**|可能引起他人不满、影响旅行体验|涉及公共场合行为规范|\n|**四级（细节礼仪）**|影响个人形象和他人感受|涉及日常交往细节|\n\n---\n\n## 第二部分：公共场合通用礼仪\n\n### 2.1 交通出行礼仪\n\n#### 2.1.1 航空礼仪\n\n- **值机安检**：提前到达机场，排队等候，配合安检人员工作\n\n- **候机礼仪**：不在候机厅大声喧哗，不占用多个座位，保持安静\n\n- **机上礼仪**：\n\n    - 登机后尽快就座，将行李放入头顶行李架或前排座椅下方\n\n    - 调整座椅靠背时先询问后排乘客\n\n    - 飞机起降时关闭电子设备，系好安全带\n\n    - 不在飞机上大声交谈、看视频外放声音\n\n    - 用完卫生间后保持清洁，及时冲水\n\n- **下机礼仪**：等飞机停稳后再起身取行李，按顺序下机\n\n#### 2.1.2 铁路与公共交通礼仪\n\n- **候车礼仪**：在指定区域候车，不越过安全线\n\n- **乘车礼仪**：\n\n    - 先下后上，主动给老人、孕妇、残疾人让座\n\n    - 不占用专座，不在车厢内饮食（除指定区域外）\n\n    - 看视频戴耳机，不打电话大声喧哗\n\n    - 行李放在指定位置，不堵塞通道\n\n- **下车礼仪**：提前做好准备，到站后有序下车\n\n#### 2.1.3 出租车与网约车礼仪\n\n- 上车后主动告知目的地，系好安全带\n\n- 不在车内吸烟、吃东西、乱扔垃圾\n\n- 尊重司机，不与司机闲聊影响驾驶\n\n- 下车时检查随身物品，向司机道谢\n\n### 2.2 餐饮礼仪\n\n#### 2.2.1 通用餐饮礼仪\n\n- **入座礼仪**：等长辈或主人先入座，男士为女士拉开座椅\n\n- **点餐礼仪**：尊重他人的饮食禁忌，不强迫他人吃不吃的东西\n\n- **用餐礼仪**：\n\n    - 等所有人都上菜后再开始用餐\n\n    - 吃饭时不发出声音，不吧唧嘴\n\n    - 不用筷子敲碗碟，不把筷子插在饭上\n\n    - 夹菜时只夹自己面前的，不翻菜\n\n    - 打喷嚏或咳嗽时用纸巾捂住口鼻，转身离开餐桌\n\n- **结账礼仪**：主动提出 AA 制或轮流请客，不抢单也不逃单\n\n#### 2.2.2 不同餐饮类型礼仪\n\n- **中餐礼仪**：\n\n    - 圆桌用餐时，主位留给长辈或主人\n\n    - 转动转盘时先询问他人意见\n\n    - 敬酒时自己的杯子低于长辈的杯子\n\n- **西餐礼仪**：\n\n    - 左手拿叉，右手拿刀\n\n    - 餐巾放在腿上，暂时离席时放在椅子上\n\n    - 喝汤时不发出声音，用勺子从里向外舀\n\n    - 吃面包时用手撕成小块吃\n\n- **日料礼仪**：\n\n    - 吃寿司时一口吃下，蘸酱油时只蘸鱼肉部分\n\n    - 吃拉面时可以发出声音，表示好吃\n\n    - 不用筷子传递食物\n\n### 2.3 住宿礼仪\n\n- **入住礼仪**：\n\n    - 礼貌对待酒店工作人员，主动出示证件\n\n    - 不损坏酒店设施，如有损坏及时赔偿\n\n- **房间礼仪**：\n\n    - 保持房间整洁，不在墙上乱涂乱画\n\n    - 晚上不要大声喧哗，以免影响其他客人休息\n\n    - 不在房间内吸烟（除非有吸烟房）\n\n- **退房礼仪**：\n\n    - 提前整理好行李，按时退房\n\n    - 带走所有个人物品，检查是否有遗漏\n\n    - 将房间恢复到基本整洁的状态\n\n### 2.4 景区游览礼仪\n\n- **购票礼仪**：排队购票，不插队，不购买黄牛票\n\n- **游览礼仪**：\n\n    - 遵守景区规定，不进入未开放区域\n\n    - 不触摸、不刻画文物古迹，不使用闪光灯拍照\n\n    - 不采摘花草、不破坏植被、不投喂野生动物\n\n    - 不在景区内大声喧哗、追逐打闹\n\n- **拍照礼仪**：\n\n    - 不随意拍摄他人，如需拍摄请先征得同意\n\n    - 不在禁止拍照的区域拍照\n\n    - 拍照时不影响他人游览\n\n---\n\n## 第三部分：不同目的地特色礼仪\n\n### 3.1 国内目的地特色礼仪\n\n#### 3.1.1 少数民族地区礼仪\n\n|民族|主要禁忌|注意事项|\n|---|---|---|\n|**藏族**|不踩门槛、不触摸佛像和法器、不直呼活佛名字|进寺庙需脱帽，顺时针转经，接受哈达时双手接过|\n|**蒙古族**|不踩门槛、不摸别人的头、不打狗|敬酒时双手接过，如不能喝酒可沾唇示意|\n|**回族**|不吃猪肉、不饮酒、不谈论猪|进入清真寺需脱鞋，女性需戴头巾|\n|**傣族**|不摸别人的头、不进主人的卧室、不坐门槛|泼水节时不要拒绝别人泼水|\n|**彝族**|不踩门槛、不摸别人的头、不吹口哨|火把节时不要用灭火器灭火|\n\n#### 3.1.2 宗教圣地礼仪\n\n- **佛教圣地**：\n\n    - 进入寺庙需脱帽，穿着得体，不穿短裤、短裙、吊带衫\n\n    - 不触摸佛像和法器，不拍照（除非允许）\n\n    - 顺时针绕佛塔和寺庙\n\n    - 保持安静，不喧哗\n\n- **道教圣地**：\n\n    - 进入道观需整理衣冠，不穿奇装异服\n\n    - 不随意触摸神像和法器\n\n    - 遇到道士行拱手礼，不握手\n\n- **伊斯兰教圣地**：\n\n    - 进入清真寺需脱鞋，女性需戴头巾，男性需穿长裤\n\n    - 不饮酒、不吃猪肉\n\n    - 礼拜时间不要打扰穆斯林\n\n### 3.2 境外目的地特色礼仪\n\n#### 3.2.1 亚洲热门国家礼仪\n\n|国家|主要禁忌|注意事项|\n|---|---|---|\n|**泰国**|不摸别人的头、不左手递东西、不谈论王室|进入寺庙需脱鞋，女性不能触碰僧侣|\n|**日本**|不随地吐痰、不边走边吃、不大声喧哗|进家门需脱鞋，鞠躬问候，不用筷子传递食物|\n|**韩国**|不摸别人的头、不左手递东西、不谈论政治|长辈先动筷，喝酒时转身背对着长辈|\n|**新加坡**|不随地吐痰、不乱扔垃圾、不嚼口香糖|罚款非常严格，遵守所有公共规定|\n|**印度**|不摸别人的头、不左手递东西、不吃牛肉|进入寺庙需脱鞋，用右手吃饭|\n\n#### 3.2.2 欧洲热门国家礼仪\n\n|国家|主要禁忌|注意事项|\n|---|---|---|\n|**法国**|不谈论政治、不询问个人隐私、不插队|见面行贴面礼，女士优先|\n|**英国**|不谈论政治、不询问个人隐私、不插队|排队是英国文化的核心，非常注重秩序|\n|**德国**|不谈论纳粹、不迟到、不浪费食物|非常守时，注重规则和纪律|\n|**意大利**|不谈论黑手党、不随地吐痰、不插队|吃饭时间较晚，中午 12 点后才开门营业|\n|**西班牙**|不谈论政治、不随地吐痰、不插队|午休时间（14:00-17:00）大部分商店关门|\n\n#### 3.2.3 其他热门地区礼仪\n\n- **美国**：\n\n    - 不谈论政治、宗教和种族问题\n\n    - 不询问个人隐私（年龄、收入、婚姻状况）\n\n    - 非常注重个人空间，不要离别人太近\n\n    - 小费文化：餐厅 15%-20%，出租车 15%-20%，酒店行李员 1-2 美元 / 件\n\n- **澳大利亚**：\n\n    - 不谈论政治和种族问题\n\n    - 非常注重平等，不要摆架子\n\n    - 喜欢直呼其名，不喜欢过于正式的称呼\n\n- **中东国家**：\n\n    - 不饮酒、不吃猪肉、不谈论政治和宗教\n\n    - 女性需穿着保守，遮盖肩膀和膝盖\n\n    - 男女之间不要有肢体接触\n\n    - 拍照前需征得同意，不要拍摄女性和军事设施\n\n---\n\n## 第四部分：通用旅行穿搭原则\n\n### 4.1 穿搭核心原则\n\n- **舒适优先**：旅行需要长时间走路和活动，优先选择舒适、透气、轻便的衣物\n\n- **实用为主**：选择多功能、易搭配、易打理的衣物，减少行李重量\n\n- **因地制宜**：根据目的地的气候、文化和活动类型选择合适的穿搭\n\n- **尊重文化**：在宗教圣地和保守地区穿着得体，避免冒犯当地人\n\n- **美观得体**：在舒适实用的基础上，选择适合自己风格的衣物，提升旅行体验\n\n### 4.2 行李打包原则\n\n- **精简原则**：只带必需品，尽量减少行李数量和重量\n\n- **叠穿原则**：选择可以叠穿的衣物，适应不同温度变化\n\n- **分类原则**：将衣物、鞋子、洗漱用品等分类打包，方便取用\n\n- **备用原则**：准备一套备用衣物，以防意外情况\n\n- **环保原则**：选择可重复使用的行李袋和洗漱用品，减少一次性用品的使用\n\n### 4.3 2026 年旅行穿搭新趋势\n\n- **可持续穿搭**：选择环保材料制成的衣物，支持可持续时尚\n\n- **多功能单品**：一件衣服多种穿法，如可变形的外套、可拆袖的衬衫\n\n- **智能穿搭**：带有防晒、防蚊、速干、保暖等功能的智能面料\n\n- **轻量便携**：超轻、可折叠的衣物和鞋子，方便携带\n\n- **国潮风**：融入中国传统元素的穿搭，既时尚又有文化特色\n\n---\n\n## 第五部分：不同场景穿搭指南\n\n### 5.1 按气候类型穿搭\n\n#### 5.1.1 热带 / 亚热带气候\n\n- **必备单品**：短袖 T 恤、短裤、短裙、连衣裙、凉鞋、遮阳帽、太阳镜、防晒霜\n\n- **穿搭建议**：\n\n    - 选择透气、吸汗、速干的面料，如棉、麻、冰丝\n\n    - 颜色选择浅色系，反射阳光，更凉爽\n\n    - 准备一件薄外套，应对空调房和早晚温差\n\n    - 海边游玩准备泳衣、沙滩裤和防晒衣\n\n#### 5.1.2 温带气候\n\n- **必备单品**：长袖衬衫、薄外套、牛仔裤、休闲裤、运动鞋、薄毛衣\n\n- **穿搭建议**：\n\n    - 采用叠穿法，方便根据温度变化增减衣物\n\n    - 选择舒适、耐磨的面料，适合长时间走路\n\n    - 准备一件防风防雨的外套，应对突发天气\n\n#### 5.1.3 寒带 / 高山气候\n\n- **必备单品**：羽绒服、冲锋衣、保暖内衣、毛衣、厚裤子、雪地靴、帽子、围巾、手套\n\n- **穿搭建议**：\n\n    - 采用三层穿衣法：内层排汗、中层保暖、外层防风防水\n\n    - 选择轻便、保暖的面料，如鹅绒、抓绒\n\n    - 注意头部、手部和脚部的保暖，这些部位最容易散失热量\n\n### 5.2 按旅行类型穿搭\n\n#### 5.2.1 都市休闲游\n\n- **风格定位**：时尚、舒适、百搭\n\n- **必备单品**：T 恤、衬衫、牛仔裤、休闲裤、连衣裙、运动鞋、帆布鞋、小背包\n\n- **穿搭建议**：\n\n    - 选择简约、百搭的款式，方便搭配\n\n    - 可以适当加入一些流行元素，提升时尚感\n\n    - 准备一双舒适的运动鞋，适合长时间逛街\n\n#### 5.2.2 古镇古村游\n\n- **风格定位**：文艺、复古、国风\n\n- **必备单品**：棉麻衬衫、长裙、旗袍、汉服、布鞋、草帽、油纸伞\n\n- **穿搭建议**：\n\n    - 选择棉麻、丝绸等天然面料，与古镇的氛围更搭\n\n    - 颜色选择素雅的色调，如白色、米色、浅蓝、浅绿\n\n    - 可以搭配一些国风配饰，如玉镯、玉佩、折扇\n\n#### 5.2.3 海滨度假游\n\n- **风格定位**：清新、浪漫、休闲\n\n- **必备单品**：泳衣、沙滩裤、防晒衣、连衣裙、短裤、凉鞋、草帽、太阳镜\n\n- **穿搭建议**：\n\n    - 选择鲜艳、明亮的颜色，与大海和沙滩形成对比\n\n    - 准备一件轻薄的防晒衣，防止晒伤\n\n    - 海边拍照可以选择飘逸的长裙，效果更好\n\n#### 5.2.4 山区徒步游\n\n- **风格定位**：运动、实用、安全\n\n- **必备单品**：速干衣、冲锋衣、徒步裤、登山鞋、登山杖、背包、帽子、太阳镜\n\n- **穿搭建议**：\n\n    - 选择专业的户外服装，具有防水、防风、透气、耐磨等功能\n\n    - 鞋子选择防滑、耐磨的登山鞋，保护脚踝\n\n    - 准备一件保暖的外套，山区温度变化大\n\n#### 5.2.5 宗教场所游\n\n- **风格定位**：庄重、得体、保守\n\n- **必备单品**：长袖衬衫、长裤、长裙、平底鞋、披肩\n\n- **穿搭建议**：\n\n    - 穿着保守，遮盖肩膀和膝盖\n\n    - 避免穿短裤、短裙、吊带衫、露背装\n\n    - 女性可以准备一条披肩，进入寺庙时遮盖头部和肩膀\n\n#### 5.2.6 商务旅行\n\n- **风格定位**：专业、干练、得体\n\n- **必备单品**：西装、衬衫、西裤、连衣裙、高跟鞋、皮鞋、公文包\n\n- **穿搭建议**：\n\n    - 选择深色系的西装，显得专业稳重\n\n    - 衬衫选择白色、浅蓝色等经典颜色\n\n    - 准备一双舒适的高跟鞋或皮鞋，适合长时间走路\n\n---\n\n## 第六部分：不同人群穿搭指南\n\n### 6.1 亲子游穿搭\n\n- **原则**：舒适、安全、方便、亲子装\n\n- **必备单品**：\n\n    - 儿童：舒适的棉质衣物、运动鞋、防晒衣、帽子、围兜、备用衣物\n\n    - 家长：舒适的休闲装、运动鞋、大容量背包\n\n- **穿搭建议**：\n\n    - 选择颜色鲜艳的亲子装，方便在人群中找到孩子\n\n    - 儿童衣物选择宽松、透气的面料，方便活动\n\n    - 准备多套备用衣物，孩子容易弄脏衣服\n\n    - 给孩子穿防滑的鞋子，防止摔倒\n\n### 6.2 老年游穿搭\n\n- **原则**：舒适、保暖、安全、方便\n\n- **必备单品**：宽松的棉质衣物、软底鞋、保暖外套、帽子、围巾、手套\n\n- **穿搭建议**：\n\n    - 选择宽松、舒适的衣物，不要穿紧身衣\n\n    - 鞋子选择软底、防滑的老年鞋，保护关节\n\n    - 注意保暖，根据温度变化及时增减衣物\n\n    - 衣服选择容易穿脱的款式，方便上厕所\n\n### 6.3 情侣游穿搭\n\n- **原则**：协调、时尚、浪漫、有纪念意义\n\n- **必备单品**：情侣装、连衣裙、衬衫、牛仔裤、运动鞋、帆布鞋\n\n- **穿搭建议**：\n\n    - 可以选择同色系、同款式或同元素的情侣装，既协调又不刻意\n\n    - 女生可以穿漂亮的连衣裙，男生搭配衬衫或 T 恤\n\n    - 准备一双舒适的鞋子，适合长时间走路\n\n    - 可以搭配一些情侣配饰，如情侣手链、情侣项链\n\n### 6.4 独行游穿搭\n\n- **原则**：舒适、实用、安全、低调\n\n- **必备单品**：舒适的休闲装、运动鞋、防盗包、帽子、太阳镜\n\n- **穿搭建议**：\n\n    - 选择低调、不显眼的衣物，避免穿得过于华丽\n\n    - 准备一个防盗包，将贵重物品贴身携带\n\n    - 鞋子选择舒适、防滑的运动鞋，适合长时间走路\n\n    - 衣服选择容易搭配的款式，减少行李数量\n\n---\n\n## 第七部分：实用穿搭小贴士\n\n### 7.1 行李打包技巧\n\n- **卷衣法**：将衣服卷成卷，比折叠更节省空间，还能减少褶皱\n\n- **收纳袋分类**：使用不同颜色的收纳袋将衣物、鞋子、洗漱用品分类\n\n- **鞋子收纳**：将鞋子放入鞋袋中，避免弄脏其他衣物\n\n- **内衣收纳**：使用内衣收纳盒，保持内衣整洁\n\n- **重物放底部**：将重物放在行李箱底部，拉起来更省力\n\n### 7.2 衣物护理技巧\n\n- **防皱技巧**：\n\n    - 选择不易皱的面料，如化纤、混纺\n\n    - 衣服卷成卷，减少褶皱\n\n    - 到达酒店后，将衣服挂起来，用热水澡的蒸汽熨平褶皱\n\n- **去污技巧**：\n\n    - 随身携带去污笔，及时处理污渍\n\n    - 不同污渍用不同的方法处理，如油渍用洗洁精，果汁用白醋\n\n- **速干技巧**：\n\n    - 选择速干面料的衣物\n\n    - 洗完衣服后用毛巾吸干水分，然后挂在通风处\n\n    - 可以用酒店的吹风机吹干衣物\n\n### 7.3 配饰选择技巧\n\n- **帽子**：不仅可以遮阳防晒，还能提升穿搭的时尚感\n\n- **太阳镜**：保护眼睛，同时也是很好的配饰\n\n- **围巾**：既可以保暖，又可以搭配衣服，增加层次感\n\n- **包包**：选择一个实用又百搭的包包，既能装东西又能提升气质\n\n- **鞋子**：鞋子是穿搭的灵魂，选择一双舒适又好看的鞋子非常重要\n\n### 7.4 特殊情况穿搭技巧\n\n- **飞机穿搭**：\n\n    - 穿着舒适、宽松的衣物，方便长时间坐着\n\n    - 准备一件薄外套，飞机上空调比较冷\n\n    - 穿方便脱穿的鞋子，过安检时更方便\n\n- **雨天穿搭**：\n\n    - 准备一件防水的外套和雨鞋\n\n    - 选择深色的衣物，不容易显脏\n\n    - 带一个防水的包包，保护电子设备\n\n- **雪天穿搭**：\n\n    - 采用三层穿衣法，注意保暖\n\n    - 穿防滑的雪地靴，防止摔倒\n\n    - 戴帽子、围巾和手套，保护头部、手部和颈部\n\n---\n\n## 第八部分：常见误区与避坑指南\n\n### 8.1 礼仪误区\n\n- **过度热情**：有些地方的人比较内敛，过度热情可能会引起反感\n\n- **以己度人**：用自己的文化标准去衡量别人的行为，容易产生误解\n\n- **忽视细节**：一些看似不重要的细节，可能会冒犯当地人\n\n- **不懂装懂**：不了解当地文化时，不要不懂装懂，虚心请教更受欢迎\n\n- **随意拍照**：随意拍摄当地居民和宗教场所，是非常不礼貌的行为\n\n### 8.2 穿搭误区\n\n- **只注重美观不注重舒适**：旅行需要长时间走路，舒适比美观更重要\n\n- **带太多衣服**：带太多衣服不仅增加行李重量，还会浪费时间在选择上\n\n- **不考虑目的地文化**：在宗教圣地和保守地区穿着暴露，会冒犯当地人\n\n- **不看天气预报**：不提前了解目的地的天气，带错衣服会影响旅行体验\n\n- **穿新鞋旅行**：新鞋容易磨脚，旅行前一定要先穿一段时间磨合',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:47:57', '2026-06-15 14:47:57');
INSERT INTO `rag_knowledge_document`
VALUES (303, '签证与出入境攻略篇', '',
        '# 签证与出入境攻略篇\n\n## 第一部分：签证办理通用流程\n\n### 1.1 签证类型与选择\n\n|签证类型|适用场景|停留时间|办理难度|\n|---|---|---|---|\n|**旅游签证（L签）**|旅游、观光、探亲访友|通常15-90天|较低|\n|**商务签证（M签）**|商务考察、会议、洽谈|通常30-180天|中等|\n|**学生签证（F签）**|留学、交流学习|根据学习时长|较高|\n|**过境签证**|经停第三国前往目的地|通常24-72小时|低|\n|**电子签证（E-visa）**|在线申请，无需邮寄护照|通常15-90天|低|\n\n### 1.2 签证办理10步标准流程\n\n1. **确定目的地和签证类型**：根据旅行目的和目的地选择合适的签证类型\n\n2. **查询签证要求**：访问目的地国家驻华使领馆官网，查询最新的签证要求和材料清单\n\n3. **准备申请材料**：按照要求准备所有申请材料，确保材料真实、完整、有效\n\n4. **填写申请表**：在线填写或下载填写签证申请表，确保信息准确无误\n\n5. **预约签证时间**：在线预约签证申请时间或递交材料时间\n\n6. **递交申请材料**：按照预约时间前往签证中心或使领馆递交申请材料\n\n7. **缴纳签证费用**：缴纳签证申请费和服务费\n\n8. **生物信息采集**：部分国家需要采集指纹和照片\n\n9. **等待签证审批**：等待签证审批结果，通常需要3-30个工作日\n\n10. **领取签证**：签证审批通过后，领取护照和签证，检查签证信息是否正确\n\n### 1.3 通用申请材料清单\n\n- **护照**：有效期不少于6个月，至少有2页空白签证页\n\n- **签证申请表**：完整填写并签名\n\n- **照片**：符合目的地国家要求的近期免冠彩色照片\n\n- **身份证明**：身份证、户口本复印件\n\n- **旅行证明**：往返机票预订单、酒店预订单、行程单\n\n- **资金证明**：银行流水、存款证明、在职证明、学生证明等\n\n- **其他材料**：根据不同国家和签证类型的要求提供\n\n---\n\n## 第二部分：主要国家/地区签证政策（2026最新）\n\n### 2.1 互免签证国家/地区\n\n- **互免普通护照签证（30天为主）**：新加坡、马来西亚、泰国、阿联酋、塞尔维亚、毛里求斯、斐济、卡塔尔、白俄罗斯、波黑\n\n- **俄罗斯**：互免签证至2026年9月14日，每次停留不超过30天，每年累计不超过90天\n\n- **巴西**：2026年5月11日起互免签证，每次停留不超过30天，每年累计不超过90天\n\n- **欧盟申根区**：法国、德国、意大利、西班牙、荷兰、瑞士等27国，持普通护照可免签入境，每次停留不超过90天，每180天累计不超过90天\n\n- **英国**：2026年1月1日起互免签证，每次停留不超过6个月\n\n### 2.2 单方面免签国家/地区\n\n- **亚洲**：韩国济州岛（30天）、日本（15天）、菲律宾（14天，仅限马尼拉/宿务）、伊朗（21天）、印度尼西亚（30天）\n\n- **非洲**：摩洛哥（90天）、突尼斯（90天）、塞舌尔（30天）、毛里塔尼亚（30天）\n\n- **美洲**：厄瓜多尔（90天）、海地（90天）、牙买加（30天）、多米尼克（30天）\n\n- **大洋洲**：萨摩亚（60天）、斐济（30天）、瓦努阿图（30天）\n\n### 2.3 热门国家电子签证政策\n\n- **越南**：电子签E-visa单次25美元90天，多次50美元90天，支持30多个海陆空口岸入境\n\n- **土耳其**：电子签60美元，有效期180天，单次停留不超过30天\n\n- **印度**：电子签80美元，有效期1年，多次入境，每次停留不超过90天\n\n- **澳大利亚**：电子旅行许可（ETA）20澳元，有效期1年，多次入境，每次停留不超过3个月\n\n- **新西兰**：电子签证165新西兰元，有效期5年，多次入境，每次停留不超过3个月\n\n### 2.4 热门国家签证注意事项\n\n- **美国**：\n\n    - 所有持10年有效期B1/B2签证的中国公民，赴美前必须在EVUS系统登记信息\n\n    - 2026年世界杯期间，部分B1/B2签证申请人需缴纳5000-15000美元不等的可退还保证金\n\n    - 面签时需准备充分的材料，证明自己有牢固的约束力，会按时回国\n\n- **日本**：\n\n    - 2026年1月1日起，中国公民可免签入境日本15天\n\n    - 如需停留超过15天，需提前申请签证\n\n- **泰国**：\n\n    - 2026年继续对中国公民实行免签政策，每次停留不超过30天\n\n    - 入境时需携带足额现金证明（个人10000泰铢，家庭20000泰铢）\n\n- **新加坡**：\n\n    - 互免签证，每次停留不超过30天\n\n    - 入境时需填写电子入境卡\n\n---\n\n## 第三部分：出入境流程与注意事项\n\n### 3.1 出境流程\n\n1. **办理值机**：提前2-3小时到达机场，凭护照办理值机和托运行李\n\n2. **边防检查**：填写出境卡（部分国家已取消），接受边防检查，出示护照、签证、机票\n\n3. **安全检查**：接受安全检查，禁止携带易燃易爆、管制刀具等违禁物品\n\n4. **候机与登机**：在指定候机区候机，听到登机通知后排队登机\n\n### 3.2 入境流程\n\n1. **边防检查**：下飞机后前往边防检查处，出示护照、签证、入境卡、往返机票、酒店预订单\n\n2. **提取行李**：通过边防检查后，前往行李提取处提取托运行李\n\n3. **海关检查**：接受海关检查，申报携带的物品，禁止携带违禁物品\n\n4. **入境**：通过海关检查后，即可入境\n\n### 3.3 出入境禁止携带物品\n\n- **禁止出境物品**：\n\n    - 文物、珍贵动植物及其制品\n\n    - 涉及国家秘密的文件、资料和其他物品\n\n    - 濒危和珍贵动植物及其种子、繁殖材料\n\n    - 管制刀具、枪支弹药、易燃易爆物品\n\n    - 毒品、精神药品、麻醉药品\n\n- **禁止入境物品**：\n\n    - 新鲜水果、蔬菜、肉类、蛋类、奶制品等动植物产品\n\n    - 种子、苗木、土壤\n\n    - 毒品、精神药品、麻醉药品\n\n    - 枪支弹药、管制刀具、易燃易爆物品\n\n    - 反动、淫秽、色情的印刷品、音像制品\n\n### 3.4 海关申报规定\n\n- **中国出境申报**：\n\n    - 携带人民币现钞超过20000元，或外币现钞折合超过5000美元，需向海关申报\n\n    - 携带文物、金银制品、电子产品等贵重物品，需向海关申报\n\n- **外国入境申报**：\n\n    - 不同国家对现金携带的规定不同，通常超过10000美元或等值货币需申报\n\n    - 携带食品、药品、动植物产品等需向海关申报\n\n    - 禁止携带违禁物品入境，否则将被没收并罚款\n\n---\n\n## 第四部分：常见问题与解决方法\n\n### 4.1 签证被拒怎么办\n\n- **了解拒签原因**：仔细阅读拒签信，了解拒签的具体原因\n\n- **准备补充材料**：针对拒签原因准备补充材料，证明自己的情况\n\n- **重新申请签证**：在规定的时间内重新申请签证，避免重复提交相同的材料\n\n- **寻求专业帮助**：如果自己无法解决，可以寻求专业签证中介的帮助\n\n- **考虑其他目的地**：如果多次被拒，可以考虑更换其他目的地\n\n### 4.2 签证丢失或被盗怎么办\n\n- **立即报警**：向当地警方报案，取得报案证明\n\n- **联系中国驻外使领馆**：向中国驻外使领馆申请补发护照或旅行证\n\n- **联系签证颁发国使领馆**：向签证颁发国使领馆申请补发签证或出具证明\n\n- **调整行程**：根据实际情况调整行程，避免不必要的损失\n\n### 4.3 入境被拒怎么办\n\n- **保持冷静**：不要与海关人员发生冲突，保持冷静和礼貌\n\n- **了解拒入境原因**：询问海关人员拒入境的具体原因\n\n- **配合海关工作**：按照海关人员的要求配合工作\n\n- **联系中国驻外使领馆**：寻求中国驻外使领馆的帮助\n\n- **安排返程**：如果无法入境，尽快安排返程\n\n### 4.4 护照过期怎么办\n\n- **提前办理护照换发**：护照有效期不足6个月时，提前到当地出入境管理部门办理换发\n\n- **境外护照过期**：如果在境外护照过期，联系中国驻外使领馆申请补发护照或旅行证\n\n- **注意事项**：护照过期后不能出境，必须提前换发\n\n---\n\n## 第五部分：实用工具与信息\n\n### 5.1 官方信息查询渠道\n\n- **中国领事服务网**：http://cs.mfa.gov.cn/，提供各国签证信息、领事保护信息\n\n- **目的地国家驻华使领馆官网**：查询最新的签证政策和申请要求\n\n- **国家移民管理局官网**：https://s.nia.gov.cn/，提供出入境管理信息和服务\n\n- **海关总署官网**：http://www.customs.gov.cn/，提供海关规定和申报信息\n\n### 5.2 签证办理工具\n\n- **签证中心官网**：如VFS Global、BLS International，提供在线预约、进度查询服务\n\n- **携程/飞猪签证频道**：提供签证代办服务，方便快捷\n\n- **支付宝/微信**：部分国家支持在支付宝或微信上申请电子签证\n\n- **翻译软件**：如Google翻译、有道翻译官，用于翻译申请材料\n\n### 5.3 紧急联系方式\n\n- **外交部全球领事保护与服务应急热线**：+86-10-12308\n\n- **中国驻外使领馆紧急电话**：可在中国领事服务网查询\n\n- **当地报警电话**：可在入境时查看入境卡或咨询酒店工作人员\n\n- **当地急救电话**：可在入境时查看入境卡或咨询酒店工作人员\n\n',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:48:08', '2026-06-15 14:48:08');
INSERT INTO `rag_knowledge_document`
VALUES (304, '美食与购物攻略篇', '',
        '# 美食与购物攻略篇\n\n## 第一部分：美食探索通用原则\n\n### 1.1 美食选择黄金法则\n\n- **本地人优先**：选择本地人常去的餐馆，避开景区主街和游客扎堆的地方\n\n- **性价比为王**：价格过高或过低的餐馆都要谨慎，中等价位通常性价比最高\n\n- **卫生第一**：观察餐馆的卫生状况，选择明厨亮灶、客流量大的餐馆\n\n- **特色优先**：尝试当地独有的特色美食，避免在旅行中吃全国连锁的快餐\n\n- **适量品尝**：不要一次点太多，少量多样品尝不同的美食\n\n### 1.2 美食探索渠道对比\n\n|渠道类型|优点|缺点|适用人群|\n|---|---|---|---|\n|**本地居民推荐**|最正宗、最地道、性价比最高|需要有本地朋友或主动询问|深度游、自由行游客|\n|**大众点评/美团**|信息全面、有用户评价、有团购优惠|存在刷单和虚假评价|所有游客|\n|**小红书/抖音**|有图片和视频参考、能发现网红店|过度营销、容易踩坑|年轻游客、喜欢打卡的游客|\n|**旅游攻略**|有详细的美食推荐和避坑指南|信息可能过时|做攻略的游客|\n|**酒店前台推荐**|方便快捷、相对靠谱|可能有合作关系、推荐有限|商务游客、懒人游客|\n\n---\n\n## 第二部分：不同场景美食攻略\n\n### 2.1 城市美食攻略\n\n- **核心区域**：老城区、居民区、大学周边是美食聚集地\n\n- **必吃类型**：当地特色小吃、老字号餐馆、市井大排档\n\n- **避坑提示**：\n\n    - 不要在火车站、汽车站、景区门口吃饭\n\n    - 不要相信出租车司机推荐的\"特色餐馆\"\n\n    - 点菜前先看菜单和价格，避免\"天价菜\"\n\n- **2026年城市美食新趋势**：\n\n    - 社区小馆兴起，主打家常菜和性价比\n\n    - 融合菜流行，将不同菜系的特色结合起来\n\n    - 健康饮食成为主流，轻食、素食餐厅越来越多\n\n### 2.2 古镇古村美食攻略\n\n- **核心区域**：古镇外围的居民区、古镇内的老字号\n\n- **必吃类型**：当地传统糕点、农家菜、特色小吃\n\n- **避坑提示**：\n\n    - 古镇主街的餐馆价格通常是外面的2-3倍\n\n    - 不要购买古镇内包装精美的\"特产美食\"\n\n    - 可以尝试古镇内的早餐，通常比较正宗且便宜\n\n- **推荐体验**：在古镇的茶馆里喝一杯当地的茶，品尝传统点心\n\n### 2.3 海滨度假美食攻略\n\n- **核心区域**：海鲜市场、渔村、居民区的海鲜餐馆\n\n- **必吃类型**：新鲜海鲜、当地特色海鲜做法、热带水果\n\n- **避坑提示**：\n\n    - 海鲜一定要买活的，当面称重，要求去皮\n\n    - 不要相信\"低价海鲜\"的宣传，一分钱一分货\n\n    - 海鲜加工前确认加工费和做法\n\n    - 不要吃生海鲜或未煮熟的海鲜，避免食物中毒\n\n- **推荐体验**：自己去海鲜市场买海鲜，然后找餐馆加工\n\n### 2.4 山区自然景区美食攻略\n\n- **核心区域**：山下县城、景区门口的农家乐\n\n- **必吃类型**：当地农家菜、山珍野味、特色主食\n\n- **避坑提示**：\n\n    - 景区内的餐馆价格高且味道一般，尽量在山下吃饭\n\n    - 不要食用野生动物，保护生态环境\n\n    - 山区饮食通常比较油腻，肠胃不好的人提前准备肠胃药\n\n- **推荐体验**：在农家乐里吃一顿地道的农家饭，体验田园生活\n\n### 2.5 境外美食攻略\n\n- **核心区域**：当地市场、居民区的小餐馆、美食街\n\n- **必吃类型**：当地特色美食、街头小吃、传统餐厅\n\n- **避坑提示**：\n\n    - 了解当地的饮食禁忌，避免冒犯当地人\n\n    - 注意饮食卫生，不要喝生水，不吃生冷食物\n\n    - 提前了解当地的小费文化，避免不必要的麻烦\n\n- **推荐体验**：参加当地的美食之旅，由本地人带领品尝地道美食\n\n---\n\n## 第三部分：购物通用原则\n\n### 3.1 购物决策三要素\n\n- **必要性**：只购买自己真正需要的东西，不要冲动消费\n\n- **性价比**：对比不同商家的价格和质量，选择性价比最高的\n\n- **便携性**：考虑物品的大小和重量，是否方便携带回国\n\n### 3.2 购物渠道对比\n\n|购物渠道|优点|缺点|适合购买的商品|\n|---|---|---|---|\n|**大型超市**|价格便宜、质量有保障、种类齐全|不能退税、人多拥挤|日用品、零食、特产|\n|**免税店**|价格便宜、可以退税、正品保障|部分商品价格虚高、限购|化妆品、奢侈品、烟酒|\n|**本地市场**|可以砍价、能买到特色商品|质量参差不齐、容易被宰|手工艺品、纪念品、当地特产|\n|**购物中心**|环境好、品牌齐全、服务好|价格高|服装、鞋包、电子产品|\n|**官方旗舰店**|正品保障、售后好|价格高|奢侈品、电子产品|\n\n---\n\n## 第四部分：不同类型购物攻略\n\n### 4.1 特产购物攻略\n\n- **购买原则**：\n\n    - 选择当地独有的、不易变质的特产\n\n    - 优先购买有地理标志认证的特产\n\n    - 不要购买景区内的特产，价格高且质量差\n\n- **常见特产分类**：\n\n    - **食品类**：茶叶、糕点、干货、调味品\n\n    - **手工艺品类**：陶瓷、刺绣、木雕、银饰\n\n    - **其他类**：丝绸、茶叶、中药材\n\n- **避坑提示**：\n\n    - 不要相信\"祖传秘方\"、\"包治百病\"的虚假宣传\n\n    - 购买特产时保留好发票和收据\n\n    - 注意特产的保质期和储存方法\n\n### 4.2 纪念品购物攻略\n\n- **购买原则**：\n\n    - 选择有纪念意义、小巧轻便的纪念品\n\n    - 避免购买全国景区都有的义乌货\n\n    - 优先购买有当地文化特色的纪念品\n\n- **推荐纪念品**：\n\n    - 明信片、冰箱贴、钥匙扣\n\n    - 当地特色的文具、饰品\n\n    - 博物馆的文创产品\n\n- **避坑提示**：\n\n    - 不要购买价格昂贵的纪念品，除非你真的很喜欢\n\n    - 不要相信\"开光\"、\"祈福\"的纪念品\n\n    - 纪念品只是旅行的纪念，不要本末倒置\n\n### 4.3 免税店购物攻略\n\n- **2026年最新免税政策**：\n\n    - 中国公民出境购物免税额度为每人每年8000元人民币\n\n    - 海南离岛免税额度为每人每年10万元人民币\n\n    - 部分国家和地区的免税店支持支付宝和微信支付\n\n- **购物技巧**：\n\n    - 提前对比国内价格，确认确实便宜再购买\n\n    - 办理免税店会员卡，享受积分和折扣\n\n    - 关注免税店的促销活动，如打折、满减、赠品\n\n    - 购买化妆品和护肤品时，可以购买套装，性价比更高\n\n- **避坑提示**：\n\n    - 不要购买临期商品\n\n    - 保留好购物小票和退税单\n\n    - 注意免税店的提货方式和时间\n\n### 4.4 奢侈品购物攻略\n\n- **购买原则**：\n\n    - 只购买自己真正需要且经济能力允许的奢侈品\n\n    - 选择正规的免税店或官方旗舰店购买\n\n    - 保留好购物凭证和保修卡\n\n- **购物技巧**：\n\n    - 对比不同国家和地区的价格，选择最便宜的地方购买\n\n    - 关注奢侈品的打折季，如圣诞节、黑色星期五\n\n    - 购买经典款，不容易过时\n\n- **避坑提示**：\n\n    - 不要相信代购，容易买到假货\n\n    - 不要在旅游景点购买奢侈品，价格高且容易被骗\n\n    - 注意奢侈品的海关规定，避免被征税\n\n---\n\n## 第五部分：美食与购物避坑指南\n\n### 5.1 美食常见骗局\n\n- **天价菜骗局**：普通菜品标价几百上千元，结账时才发现\n\n- **阴阳菜单骗局**：给游客看的菜单价格高，给本地人看的价格低\n\n- **缺斤短两骗局**：海鲜称重时做手脚，实际重量不足\n\n- **掉包食材骗局**：点的活海鲜被换成死海鲜\n\n- **强制消费骗局**：餐具费、茶位费、服务费不提前告知\n\n**避坑方法**：\n\n- 点菜前仔细阅读菜单，确认所有菜品价格\n\n- 海鲜称重时要求去皮，自己看秤\n\n- 保留好菜单和发票，发现问题及时投诉\n\n- 选择明码标价的餐馆\n\n### 5.2 购物常见骗局\n\n- **假货骗局**：用假货冒充正品，高价出售\n\n- **高价低质骗局**：普通商品贴上\"特产\"标签，价格翻几倍\n\n- **强制购物骗局**：导游带游客到购物店，不买不让走\n\n- **抽奖骗局**：声称中奖，诱导游客购买高价商品\n\n- **换汇骗局**：以\"优惠汇率\"换汇，实际是假币或汇率很低\n\n**避坑方法**：\n\n- 不要相信\"天上掉馅饼\"的好事\n\n- 只在正规渠道购买商品\n\n- 保留好购物凭证，发现问题及时维权\n\n- 不要和陌生人交易，避免被骗\n\n---\n\n## 第六部分：实用工具与技巧\n\n### 6.1 美食工具推荐\n\n- **大众点评/美团**：查询餐馆信息、用户评价、团购优惠\n\n- **小红书/抖音**：发现网红店和美食攻略\n\n- **下厨房**：学习当地美食的做法\n\n- **美食杰**：提供各地美食介绍和做法\n\n- **TripAdvisor**：全球美食和餐厅推荐\n\n### 6.2 购物工具推荐\n\n- **什么值得买**：比价和优惠券推荐\n\n- **慢慢买**：历史价格查询和比价\n\n- **免税店官方APP**：查询商品价格和库存\n\n- **支付宝/微信**：移动支付和退税\n\n- **海关总署APP**：查询海关规定和免税额度\n\n### 6.3 实用技巧\n\n- **美食技巧**：\n\n    - 吃饭时间避开高峰，不用排队\n\n    - 可以点半份菜，避免浪费\n\n    - 尝试当地的街头小吃，通常很正宗\n\n- **购物技巧**：\n\n    - 货比三家，不要急于购买\n\n    - 可以适当砍价，尤其是在本地市场\n\n    - 购买易碎物品时，要求商家包装好\n',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:48:22', '2026-06-15 14:48:22');
INSERT INTO `rag_knowledge_document`
VALUES (305, '行程规划方法论篇', '',
        '# 行程规划方法论篇\n\n## 第一部分：行程规划核心原则\n\n### 1.1 规划四要素平衡法则\n\n- **时间**：合理分配每天的行程时间，避免过于紧凑或松散\n\n- **预算**：根据自己的经济能力制定预算，合理分配各项费用\n\n- **兴趣**：优先安排自己感兴趣的景点和活动\n\n- **体力**：根据自己和同行人的体力情况安排行程，避免过度劳累\n\n### 1.2 行程规划理念\n\n- **体验优先**：远离商业化陷阱，深挖本地小众玩法，拒绝走马观花\n\n- **错峰出行**：节假日避开一线热门景区，选周边小众秘境；热门地选工作日、清晨/傍晚游览\n\n- **季节适配**：春赏花、夏避暑、秋赏色、冬避寒玩雪，只追当季最美景致\n\n- **灵活调整**：预留一定的弹性时间，应对突发情况和临时兴趣\n\n---\n\n## 第二部分：行程规划10步标准流程\n\n### 2.1 明确旅行目标与风格\n\n- **旅行风格定位**：休闲度假、文化探索、户外探险、亲子娱乐、商务出行\n\n- **核心诉求**：放松身心、增长见识、拍照打卡、品尝美食、社交互动\n\n- **同行人员**：考虑同行人的年龄、兴趣、体力和特殊需求\n\n### 2.2 确定旅行时间与时长\n\n- **最佳旅行时间**：根据目的地的气候、季节和特色活动确定\n\n- **旅行时长**：\n\n    - 短途游：2-3天，适合周边城市和单一景点\n\n    - 中长途游：4-7天，适合跨省游和文化名城\n\n    - 长途游：7天以上，适合多城市串联和境外游\n\n- **避开高峰期**：避开节假日、寒暑假和旅游旺季，节省费用且体验更好\n\n### 2.3 筛选与确定目的地\n\n- **初步筛选**：根据旅行风格、时间和预算列出可能的目的地\n\n- **深入了解**：研究目的地的景点、美食、文化、交通和消费水平\n\n- **最终确定**：综合考虑各方面因素，选择最适合自己的目的地\n\n### 2.4 研究目的地基础信息\n\n- **交通信息**：如何到达目的地，目的地内部的交通方式\n\n- **住宿信息**：不同区域的住宿特点和价格\n\n- **景点信息**：景点的开放时间、门票价格、游玩时长和预约要求\n\n- **美食信息**：当地特色美食和推荐餐馆\n\n- **天气信息**：旅行期间的天气预报，准备合适的衣物\n\n### 2.5 制定初步行程框架\n\n- **按天划分行程**：将旅行时间按天划分，每天安排1-2个核心景点\n\n- **确定游览顺序**：根据景点的地理位置和开放时间合理安排游览顺序\n\n- **预留弹性时间**：每天预留1-2小时的弹性时间，应对突发情况\n\n### 2.6 细化每日行程安排\n\n- **时间节点**：明确每天的起床时间、出发时间、游览时间、用餐时间和休息时间\n\n- **交通方式**：确定每个景点之间的交通方式和所需时间\n\n- **用餐安排**：提前了解景点附近的餐馆，安排好用餐时间\n\n- **注意事项**：记录每个景点的注意事项和游玩技巧\n\n### 2.7 预订交通与住宿\n\n- **交通预订**：提前预订机票、火车票、汽车票等长途交通\n\n- **住宿预订**：根据行程安排选择合适的住宿，提前预订\n\n- **门票预订**：提前预订热门景点的门票，避免现场排队\n\n### 2.8 制定预算计划\n\n- **总预算**：确定旅行的总预算\n\n- **费用分配**：将总预算分配到交通、住宿、餐饮、门票、购物等各个方面\n\n- **预留应急资金**：预留总预算的10%-15%作为应急资金\n\n### 2.9 行前准备\n\n- **证件准备**：身份证、护照、签证、驾驶证等\n\n- **物品准备**：衣物、洗漱用品、电子产品、常用药品等\n\n- **信息准备**：下载离线地图、翻译软件、攻略APP等\n\n- **告知家人**：将详细行程告知家人或朋友，保持联系\n\n### 2.10 行程执行与调整\n\n- **严格执行**：按照制定的行程执行，避免随意更改\n\n- **灵活调整**：根据实际情况灵活调整行程，如天气变化、景点关闭等\n\n- **记录旅行**：拍照、写日记，记录旅行的美好瞬间\n\n---\n\n## 第三部分：不同时长行程规划方法\n\n### 3.1 2-3天短途游规划\n\n- **核心原则**：少而精，重点体验1-2个核心景点\n\n- **行程安排**：\n\n    - 第一天：抵达目的地，熟悉环境，游览市区景点\n\n    - 第二天：深度游览核心景点\n\n    - 第三天：自由活动，购买特产，返程\n\n- **注意事项**：\n\n    - 选择交通便利的住宿，靠近核心景点或交通枢纽\n\n    - 不要安排太多景点，避免走马观花\n\n### 3.2 4-5天中长途游规划\n\n- **核心原则**：主次分明，兼顾经典景点和小众体验\n\n- **行程安排**：\n\n    - 第一天：抵达目的地，入住酒店，游览市区景点\n\n    - 第二天：游览核心景点A\n\n    - 第三天：游览核心景点B\n\n    - 第四天：体验小众玩法或周边景点\n\n    - 第五天：自由活动，购买特产，返程\n\n- **注意事项**：\n\n    - 合理安排交通，避免在路上浪费太多时间\n\n    - 预留半天的自由活动时间，根据自己的兴趣调整\n\n### 3.3 6-7天长途游规划\n\n- **核心原则**：深度体验，多景点串联，全面了解目的地\n\n- **行程安排**：\n\n    - 第一天：抵达目的地，入住酒店，熟悉环境\n\n    - 第二天：游览核心景点A\n\n    - 第三天：游览核心景点B\n\n    - 第四天：游览周边城市或景点\n\n    - 第五天：体验当地文化和生活\n\n    - 第六天：自由活动，购买特产\n\n    - 第七天：返程\n\n- **注意事项**：\n\n    - 提前规划好跨城市的交通，预订好车票\n\n    - 注意劳逸结合，避免过度劳累\n\n### 3.4 7天以上深度游规划\n\n- **核心原则**：慢节奏，深度体验当地文化和生活\n\n- **行程安排**：\n\n    - 每个城市或地区安排2-3天的时间\n\n    - 预留1-2天的弹性时间，应对突发情况\n\n    - 安排一些体验性强的活动，如烹饪课、手工课等\n\n- **注意事项**：\n\n    - 不要安排太多城市，避免赶路\n\n    - 可以选择长住一个地方，慢慢体验当地生活\n\n---\n\n## 第四部分：不同类型旅行规划技巧\n\n### 4.1 休闲度假游规划\n\n- **核心原则**：放松身心，慢节奏，少安排景点\n\n- **行程特点**：\n\n    - 选择度假型酒店或民宿，享受酒店设施\n\n    - 每天只安排1个轻松的活动，如散步、游泳、SPA\n\n    - 预留大量的自由活动时间\n\n- **推荐目的地**：三亚、厦门、青岛、马尔代夫、巴厘岛\n\n### 4.2 文化探索游规划\n\n- **核心原则**：深入了解当地历史文化，注重体验\n\n- **行程特点**：\n\n    - 安排参观博物馆、历史遗迹、文化景点\n\n    - 参加当地的文化活动和体验项目\n\n    - 品尝当地特色美食，了解饮食文化\n\n- **推荐目的地**：北京、西安、南京、洛阳、敦煌\n\n### 4.3 户外探险游规划\n\n- **核心原则**：安全第一，充分准备，量力而行\n\n- **行程特点**：\n\n    - 选择正规的户外俱乐部和向导\n\n    - 提前了解目的地的天气和地形\n\n    - 准备专业的户外装备和药品\n\n- **推荐目的地**：黄山、张家界、九寨沟、稻城亚丁、西藏\n\n### 4.4 亲子娱乐游规划\n\n- **核心原则**：寓教于乐，兼顾孩子和大人的需求\n\n- **行程特点**：\n\n    - 安排适合孩子的景点和活动，如动物园、游乐园、科技馆\n\n    - 每天的行程不要太紧凑，预留午休时间\n\n    - 选择亲子友好的酒店和餐馆\n\n- **推荐目的地**：上海、广州、深圳、成都、香港\n\n---\n\n## 第五部分：行程调整与优化\n\n### 5.1 常见突发情况处理\n\n- **天气变化**：调整室内外景点的顺序，优先安排室内景点\n\n- **景点关闭**：提前了解景点的开放时间，如遇关闭及时更换其他景点\n\n- **交通延误**：预留弹性时间，如遇延误及时调整后续行程\n\n- **身体不适**：立即停止行程，休息或就医，不要勉强\n\n### 5.2 行程优化技巧\n\n- **合并同类项**：将地理位置相近的景点安排在同一天\n\n- **错峰游览**：清晨或傍晚游览热门景点，避开人流高峰\n\n- **利用碎片时间**：在交通途中或等待时间安排一些轻松的活动\n\n- **删减不重要的景点**：如果时间不够，果断删减不重要的景点，保证核心景点的游览质量\n\n### 5.3 避免常见规划误区\n\n- **行程过于紧凑**：每天安排太多景点，导致走马观花，身心俱疲\n\n- **不考虑交通时间**：低估景点之间的交通时间，导致行程延误\n\n- **不预留弹性时间**：行程安排得太满，没有应对突发情况的时间\n\n- **盲目跟风**：只去网红景点，忽略了当地真正的特色\n\n- **不考虑同行人的需求**：只按照自己的兴趣安排行程，忽略了同行人的感受\n\n---\n\n## 第六部分：实用工具推荐\n\n### 6.1 行程规划工具\n\n- **Google Maps/高德地图**：导航、路线规划、景点查询\n\n- **TripIt**：自动整合行程单，离线查看\n\n- **马蜂窝/穷游**：旅游攻略、行程模板、用户分享\n\n- **携程/飞猪**：机票、酒店、门票预订\n\n- **Notion/印象笔记**：记录和整理行程\n\n### 6.2 交通查询工具\n\n- **12306**：火车票预订、查询\n\n- **飞常准/航旅纵横**：航班动态查询\n\n- **Google Flights**：全球机票比价\n\n- **Rome2Rio**：全球交通方式查询和比价\n\n- **滴滴出行/Uber**：网约车预订\n\n### 6.3 住宿预订工具\n\n- **Booking.com**：全球酒店预订，免费取消政策友好\n\n- **Airbnb**：全球民宿预订\n\n- **携程/美团**：国内酒店、民宿预订\n\n- **Agoda**：亚洲酒店预订，价格优惠\n\n### 6.4 其他实用工具\n\n- **Google翻译/有道翻译官**：语言翻译\n\n- **墨迹天气/天气通**：天气预报\n\n- **大众点评/美团**：美食、娱乐查询预订\n\n- **国家政务服务平台**：电子证件、健康码查询\n',
        '', 'published', 1200, 120, 3, 0.5000, 1, 0, '2026-06-15 14:48:30', '2026-06-15 14:48:48');

-- ----------------------------
-- Table structure for rag_vector_config
-- ----------------------------
DROP TABLE IF EXISTS `rag_vector_config`;
CREATE TABLE `rag_vector_config`
(
    `id`           bigint                                                         NOT NULL AUTO_INCREMENT COMMENT '主键 id',
    `config_key`   varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci  NOT NULL COMMENT '配置键',
    `config_value` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '配置值',
    `remark`       varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci  NULL     DEFAULT NULL COMMENT '备注',
    `created_at`   datetime                                                       NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `updated_at`   datetime                                                       NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (`id`) USING BTREE,
    UNIQUE INDEX `uk_rag_vector_config_key` (`config_key` ASC) USING BTREE
) ENGINE = InnoDB
  AUTO_INCREMENT = 6
  CHARACTER SET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RAG 向量参数配置表'
  ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rag_vector_config
-- ----------------------------
